    'ops_export_note_rank_achievements' => 'রেকর্ড করা অর্জনের তারিখ ও র‍্যাঙ্ক ইতিহাস। যেসব পুরনো লাইনে অর্জনের তারিখ নেই, সেগুলোতে বানানো তারিখ দেওয়া হয় না।',
    'ops_export_note_due_adjustments' => 'অনুরোধ করা, অনুমোদিত ও বাতিল হওয়া ক্রেডিট নোট ও ডেবিট সংশোধন। শুধু অনুমোদিত নোট বকেয়া বদলায়। মোট টাকা এই তালিকার হিসাব, হাতে পাওয়া নগদ নয়।',
    'ops_export_note_refunds' => 'সংশোধনের তারিখ অনুযায়ী কমিশন হিসাবের সংশোধন। এসব রেকর্ড ব্যাংকে টাকা ফেরত দেওয়ার প্রমাণ নয়।',
