    'ops_download_report' => 'রিপোর্ট ডাউনলোড',
    'ops_preview_finance_notice' => 'ট্রায়াল মোড · লাইভ টাকার হিসাব বন্ধ। খসড়া ও সেটিং ব্যবহার করা যাবে। আসল পেমেন্টের আগে নিয়ম ও শুরুর ব্যালেন্স অনুমোদন করুন।',
    'ops_promote_video' => 'পণ্যের ভিডিও প্রচার করুন',
    'ops_promote_video_body' => 'YouTube, Vimeo, সরাসরি MP4/WebM লিংক বা আপলোড করা ভিডিও যোগ করুন',
    'ops_promote_video_hide' => 'পণ্য প্রকাশ করে নিচে বেছে নিন। পণ্য প্রকাশ বন্ধ হলে বা ভিডিও সরালে হোমপেজে এই অংশ আপনা থেকে লুকিয়ে যাবে।',
    'ops_no_product_videos' => 'এখনো কোনো প্রকাশিত পণ্য ভিডিও নেই।',
    'ops_credit_notes' => 'বকেয়ার ক্রেডিট নোট',
    'ops_credit_notes_body' => 'ক্রেডিট নোট বাকি টাকা কমায়। ডেবিট সংশোধন আগের ক্রেডিট ফিরিয়ে আনে, মূল অর্ডার মূল্য পর্যন্ত। এর কোনোটিই হাতে পাওয়া নগদ বা কমিশনযোগ্য পেমেন্ট নয়। দাম ও সেভ করা কমিশন নিয়ম বদলায় না।',
    'ops_find_order' => 'অর্ডার খুঁজুন',
    'ops_order_number' => 'অর্ডার নম্বর',
    'ops_search_orders' => 'অর্ডার খুঁজুন',
    'ops_no_adjustable_orders' => 'সমন্বয় করার মতো কোনো অর্ডার পাওয়া যায়নি',
    'ops_no_adjustable_orders_body' => 'ক্রেডিট নোট বা ডেবিট সংশোধনের জন্য বাকি বা আংশিক পরিশোধিত অর্ডারের নম্বর দিয়ে খুঁজুন।',
    'ops_credit_notes_review' => 'প্রতিটি নোট হিসাব বিভাগের আরেকজন অনুমোদন করেন। পরিশোধিত অর্ডারের টাকা ফেরত সাধারণ ফেরতের ধাপে হয়।',
    'ops_withdrawal_policy' => 'টাকা তোলার নিয়ম',
    'ops_withdrawal_policy_body' => 'বর্তমান সর্বনিম্ন: :amount। পরিবর্তন শুধু নতুন অনুরোধে চলবে; আগের অনুরোধে সেভ করা সর্বনিম্ন ও পরিমাণ থাকবে।',
    'ops_policy_schedules_hint' => 'সবার জন্য একই রেট কমিশন সেটআপেও বদলানো যায়। ক্রেতার দিক বদলালে একজন ডিলার বা সাব-ডিলারের প্ল্যান বদলায়। পাওনাদারের দিক বদলালে শুধু ওই পার্টনারের আয় বদলায়। অর্ডার অনুমোদন হলে নতুন রেট চালু হয়। রেট বাড়ালে বাড়তি টাকা কোম্পানির ভাগ বা নির্দিষ্ট একজনের ভাগ থেকে নিন; যত বাড়াবেন, ঠিক তত কাটতে হবে। রেট কমালে বাকি টাকা কোম্পানির কাছে থাকে। প্রতিটি পরিবর্তন হিসাব বিভাগের আরেকজনকে অনুমোদন করতে হবে।',
    'ops_payroll_hint' => 'বেতন চুক্তির প্রতিটি পরিবর্তন সেভ থাকে। অনুমোদনের আগে চুক্তি, টার্গেট ও পাওয়া বোনাস দেখে নিন। অনুমোদিত এন্ট্রিতে টাকা দেওয়ার জন্য আলাদা একজন ও একটি গোপন রসিদ লাগবে।',
    'ops_reserve_payouts_hint' => 'ট্যুর পুরস্কার ওই সাব-ডিলারের নিজের ফান্ড থেকে দেওয়া হয়। অনুমোদিত পুরস্কার পার্টনারের ওয়ালেটে জমা হয়। মার্কেটিং খরচে টাকা দেওয়ার একজন লোক, আসল ব্যাংক বা বিকাশ রেফারেন্স ও রসিদ লাগবে।',
    'ops_my_territories' => 'আমার এলাকা',
    'ops_no_territory' => 'কোনো এলাকা নির্ধারিত নেই',
    'ops_no_territory_body' => 'ম্যানেজারকে আপনার সেলস এলাকা ঠিক করে দিতে বলুন।',
    'ops_accounts_partnerships_hint' => 'অ্যাকাউন্টস স্টাফ অনলাইন ও মার্কেট সেলস আবেদনও চেক করতে পারেন',
    'ops_find_partner' => 'নাম বা ডিলার কোড দিয়ে পার্টনার খুঁজুন (সর্বোচ্চ ২০০টি ফল)',
