    'ops_or' => 'অথবা',
    'ops_startup_paths' => 'নতুন শুরুতে এক্সেল ফাইল লাগে না। আমদানির পথে শুরুর খাতা যাচাইয়ের আগে এক্সেল নমুনা ফাইল ব্যবহার হয়। কোনোটিই নিজে থেকে লাইভ টাকার হিসাব চালু করে না।',
