    'ops_service_config' => 'সার্ভিস / সেটিং',
    'ops_deployment_hint' => 'ট্রায়ালের তথ্য যেমন আছে তেমন থাকবে। লাইভ চালুর এই চেকগুলো টাকার হিসাব চালু করে না বা শুরুর ব্যালেন্স অনুমোদন করে না।',
    'ops_go_live_warnings' => 'লাইভ চালুর আগে যা ঠিক করবেন (এগুলো প্রস্তুতি আটকায় না, তবে আসল ব্যবহারের আগে ঠিক করুন)',
    'ops_warn_sms_driver_logging_only' => 'এসএমএস এখনো পাঠানো হচ্ছে না (পরীক্ষা মোড)। পার্টনার লগইন OTP চালুর আগে আসল এসএমএস সার্ভিস সেট করুন।',
    'ops_warn_mail_driver_logging_only' => 'ইমেইল এখনো পাঠানো হচ্ছে না (পরীক্ষা মোড)। পাসওয়ার্ড রিসেট ইমেইলের আগে ইমেইল সার্ভিস (SMTP/SES/Postmark) সেট করুন।',
    'ops_warn_mail_from_address_is_example_placeholder' => 'প্রেরকের ইমেইল ঠিকানা এখনো নমুনা (@example.com)। লাইভ চালুর আগে আসল ঠিকানা দিন (সেটিং: MAIL_FROM_ADDRESS)।',
    'ops_warn_mail_smtp_host_is_local_development' => 'ইমেইল সার্ভার এখনো লোকাল টেস্ট সার্ভার (Mailpit)। আসল ইমেইল সার্ভার সেট করুন (সেটিং: MAIL_HOST)।',
    'ops_warn_login_otp_requires_real_sms_before_go_live' => 'লগইন OTP চালু আছে, কিন্তু এসএমএস এখনো আসলে পাঠানো হচ্ছে না। আসল এসএমএস সার্ভিস দিয়ে OTP পুরোটা পরীক্ষা করুন।',
    'ops_warn_partner_login_otp_forced_off_in_preview' => 'পার্টনার লগইন OTP চালু হিসেবে সেভ আছে, কিন্তু ট্রায়াল মোড বন্ধ (MADINA_PREVIEW_MODE=false) ও এসএমএস লাইভ না হওয়া পর্যন্ত এটি বন্ধ থাকবে।',
    'ops_warn_staff_totp_forced_off_in_preview' => 'ট্রায়াল মোড চালু থাকায় (MADINA_PREVIEW_MODE=true) স্টাফ ও মালিকের অ্যাপ কোড লগইন (2FA) বন্ধ থাকবে, কারণ ট্রায়াল মোডে এসএমএস ও ইমেইল বন্ধ।',
    'ops_warn_admin_ip_allowlist_empty' => 'অ্যাডমিন অংশের জন্য অনুমোদিত IP তালিকা নেই। ইন্টারনেটে অ্যাডমিন পাতা খোলার আগে এটি সেট করুন (MADINA_ADMIN_IP_ALLOWLIST)।',
    'ops_warn_privacy_retention_unconfigured' => 'বন্ধ হওয়া রেকর্ড কত দিন রাখা হবে তা সেট নেই। তথ্য গোপনীয়তার নিয়ম (PDPO) মানতে দিনের সংখ্যা সেট করুন (MADINA_PRIVACY_RETENTION_DAYS)।',
    'ops_warn_place_code_catalog_incomplete' => 'স্থান কোডের তালিকা এখনো সম্পূর্ণ নয়। পার্টনাররা আসলে যোগ দেওয়ার আগে স্থান কোড পাতায় ব্যবস্থাপনা ও এলাকার স্থান তৈরি করুন (টেকনিশিয়ান চাইলে তৈরি বাংলাদেশ তালিকাও যোগ করতে পারেন)।',
    'ops_warn_area_dealer_assignments_missing' => 'এখনো কোনো এলাকার ডিলার ঠিক করা হয়নি। স্থান কোড তৈরি হলে বিভাগ, জেলা, উপজেলা বা ইউনিয়নে অন্তত একজন ডিলার দিন। না হলে সেই এলাকার কমিশন কোম্পানির কাছে থেকে যাবে।',
    'ops_warn_area_dealer_coverage_incomplete' => 'এলাকার ডিলার এখনো সবাইকে ধরে না। কারো বিভাগ বা জেলায় কোনো ডিলার নেই, অথবা একাধিক ডিলার আছে, তাই সেই কমিশন কোম্পানির কাছে থাকে।',
    'ops_warn_partners_missing_place_codes' => 'কিছু সক্রিয় ডিলার/সাব-ডিলারের স্থান কোড নেই। এলাকার কমিশন লাইভ চালুর আগে আসল স্থান কোড দিয়ে তাদের অ্যাকাউন্ট এডিট করুন (বা আবার আমদানি করুন)।',
    'ops_warn_opening_balances_unverified' => 'শুরুর ব্যালেন্স এখনো দুইজন মিলে যাচাই করেননি। টাকার হিসাব লাইভ চালুর (MADINA_FINANCIAL_ACTIVATION=true) আগে এগুলো তৈরি ও যাচাই করুন।',
    'ops_warn_opening_balances_stale' => 'শুরুর ব্যালেন্সের যাচাই পুরনো হয়ে গেছে: দুইজনের যাচাইয়ের পর খাতা বদলেছে। টাকার হিসাব লাইভ চালুর (MADINA_FINANCIAL_ACTIVATION=true) আগে শুরুর ব্যালেন্স আবার জমা দিয়ে যাচাই করুন।',
    'ops_warn_commission_policy_unreviewed' => 'কমিশন নিয়মের খসড়া দ্বিতীয় একজনের যাচাইসহ প্রকাশ হয়নি। টাকার হিসাব লাইভ চালুর (MADINA_FINANCIAL_ACTIVATION=true) আগে হিসাব বিভাগের দ্বিতীয় একজন অনুমোদনকারী দিয়ে খসড়া যাচাই করে প্রকাশ করুন।',
    'ops_warn_partner_benefit_overrides_active' => 'কিছু সক্রিয় পার্টনার কোনো শর্ত ছাড়াই বিশেষ রেটে বেতন বা র‍্যাঙ্ক সুবিধা পান। টাকার হিসাব লাইভ চালুর (MADINA_FINANCIAL_ACTIVATION=true) আগে প্রতিটি বিশেষ রেট দেখে নিন, যাতে ভুল করে কোনোটি না থাকে।',
    'ops_warn_preview_mode_enabled' => 'ট্রায়াল মোড এখনো চালু (MADINA_PREVIEW_MODE=true)। আসল চালুর আগে এটি বন্ধ করুন (false দিন)। লাইভ টাকার হিসাব বন্ধ থাকলেই কেবল ট্রায়াল মোড নিরাপদ।',
