    'ops_warn_app_domain_mismatches_app_url' => 'ওয়েবসাইটের ঠিকানার সেটিং মিলছে না (APP_DOMAIN ও APP_URL)। প্যানেলের ঠিকানা ও পাসওয়ার্ড রিসেট লিংক ঠিকমতো কাজ করতে দুটো এক করুন।',
    'ops_warn_payment_collection_accounts_missing' => 'পেমেন্ট নেওয়ার কোনো চালু কোম্পানি অ্যাকাউন্ট নেই। আসল পেমেন্ট দাবি শুরুর আগে টাকা নেওয়ার জন্য অন্তত একটি ব্যাংক বা মোবাইল ব্যাংকিং অ্যাকাউন্ট যোগ করুন।',
    'ops_warn_payment_payout_accounts_missing' => 'টাকা পাঠানোর কোনো চালু কোম্পানি অ্যাকাউন্ট নেই। পার্টনাররা আসলে টাকা তোলার আগে টাকা পাঠাতে পারে এমন অন্তত একটি ব্যাংক বা মোবাইল ব্যাংকিং অ্যাকাউন্ট যোগ করুন।',
    'ops_warn_queue_driver_is_sync' => 'ব্যাকগ্রাউন্ডের কাজ সেট করা নেই (queue driver: sync/null)। আমদানি ও ব্যাকগ্রাউন্ড পেমেন্ট লাইভ চালুর আগে টেকনিশিয়ানকে ব্যাকগ্রাউন্ড ওয়ার্কার (database/redis) চালু করতে বলুন।',
    'ops_warn_scheduler_heartbeat_missing' => 'নির্দিষ্ট সময়ে চলার কাজগুলো চালু নেই। মেয়াদ পূর্ণ কমিশন ছাড় ও ব্যাকআপ সময়মতো হতে টেকনিশিয়ানকে `php artisan schedule:work` (বা cron) চালাতে বলুন।',
    'ops_warn_queue_worker_heartbeat_missing' => 'ব্যাকগ্রাউন্ড ওয়ার্কার চালু নেই। আমদানি ও ব্যাকগ্রাউন্ডের কাজ চালাতে টেকনিশিয়ানকে `php artisan queue:work --queue=imports,default` চালাতে বলুন।',
    'ops_warn_debug_mode_enabled' => 'ডিবাগ মোড চালু আছে (APP_DEBUG)। আসল ব্যবহারের আগে এটি বন্ধ করুন, যাতে ভুলের বিস্তারিত ও সার্ভারের সেটিং গোপন থাকে।',
    'ops_warn_backups_not_configured' => 'এনক্রিপ্টেড ব্যাকআপ সেট নেই — MADINA_BACKUPS_ENABLED ও ৩২+ অক্ষরের MADINA_BACKUP_PASSWORD সেট করুন, তারপর app:backup-verify দিয়ে যাচাই করুন।',
    'ops_warn_app_environment_not_production' => 'সার্ভার লাইভ মোডে সেট নেই। সবার জন্য খোলার আগে লাইভ সার্ভারে APP_ENV=production সেট করুন।',
    'ops_warn_app_url_not_https' => 'ওয়েবসাইটের ঠিকানা নিরাপদ নয় (HTTPS নেই)। আসল ব্যবহারের আগে https:// ঠিকানা (APP_URL) সেট করুন।',
    'ops_warn_session_cookies_not_hardened' => 'লগইন কুকি পুরোপুরি সুরক্ষিত নয়। লাইভ HTTPS সাইটের জন্য SESSION_SECURE_COOKIE=true ও SESSION_ENCRYPT=true সেট করুন।',
    'ops_warn_app_key_missing_or_weak' => 'অ্যাপের নিরাপত্তা কী (APP_KEY) নেই বা খুব ছোট। আসল ব্যবহারের আগে একটি শক্ত কী তৈরি করুন।',
    'ops_warn_trusted_proxies_not_configured' => 'সাইটে HTTPS আছে কিন্তু TRUSTED_PROXIES খালি। HTTPS ও ভিজিটরের IP ঠিকমতো ধরতে প্রক্সি/লোড-ব্যালেন্সারের IP রেঞ্জ সেট করুন।',
    'ops_warn_verified_backup_missing' => 'সম্প্রতি যাচাই করা কোনো ব্যাকআপ নেই। `php artisan app:backup` তারপর `php artisan app:backup-verify` চালিয়ে নতুন, ফিরিয়ে আনা যায় এমন ব্যাকআপ রাখুন।',
