    'help_manual_search_ph' => 'ফিচার, অর্ডার, কমিশন, ওয়ালেট, প্লেস কোড বা নিয়ম খুঁজুন…',
    'help_manual_no_results' => 'আপনার খোঁজার সাথে মেলে এমন কোনো গাইড পাওয়া যায়নি।',
    'help_manual_quick_nav' => 'এই গাইডে যা আছে',
