    'help_manual_feedback_prompt' => 'এই গাইডটি কি কাজে লেগেছে?',
    'help_manual_feedback_thanks' => 'ধন্যবাদ! আপনার মতামত আমাদের আরও ভালো করতে সাহায্য করবে।',
    'help_manual_filter_all' => 'সব অধ্যায়',
    // Chapter 1: getting_started
    'manual_ch_getting_started_title' => '১. শুরু করা, ড্যাশবোর্ড ও মেনু',
    'manual_ch_getting_started_badge' => 'শুরুর কথা',
    'manual_ch_getting_started_summary' => 'প্রথমবার লগইন, ড্যাশবোর্ডের কার্ড ও লাইভ হিসাব, ভাষা বদল এবং মেনু চেনার সহজ গাইড।',
    'manual_ch_getting_started_purpose' => 'মদিনা ন্যাচারাল কেয়ার প্যানেল ডিলার, সাব-ডিলার, কর্মচারী ও কোম্পানির ম্যানেজমেন্টকে এক জায়গায় যুক্ত করে। এখান থেকে পাইকারি অর্ডার, কমিশন ভাগ, ডেলিভারি ট্র্যাকিং, ওয়ালেট থেকে টাকা তোলা এবং টিম নেটওয়ার্ক আপনা থেকেই চলে।',
    'manual_ch_getting_started_why' => 'হাতে লেখা খাতার ঝামেলা, টাকার অস্পষ্ট হিসাব ও দেরিতে পেমেন্ট—এসব দূর করে। প্রতিটি লেনদেনের রেকর্ড থাকে এবং তা বদলানো যায় না, তাই প্রত্যেক অংশীদার নিজের ন্যায্য পাওনা সঙ্গে সঙ্গে দেখতে ও মিলিয়ে নিতে পারেন।',
    'manual_ch_getting_started_s1' => 'আপনার নিবন্ধিত ১১ সংখ্যার মোবাইল নম্বর ও পাসওয়ার্ড দিয়ে "লগইন" বাটনে চাপুন।',
    'manual_ch_getting_started_s2' => 'লগইনের পর প্রথমবার ড্যাশবোর্ডে ঢুকলেই একটি গাইড ট্যুর চালু হবে। কোন কার্ড কোথায় ও কিসের জন্য, তা বুঝতে ট্যুরটি শেষ করুন।',
    'manual_ch_getting_started_s3' => 'ড্যাশবোর্ডের ওপরের কার্ডগুলো দেখুন: মোট কমিশন, তোলার যোগ্য ব্যালেন্স, অপেক্ষমাণ অর্ডার ও বর্তমান র‍্যাঙ্ক।',
    'manual_ch_getting_started_s4' => 'বাম পাশের মেনু থেকে সরাসরি পণ্য তালিকা, অর্ডার, ডেলিভারি, কমিশন, নেটওয়ার্ক ও রিপোর্ট খুলুন।',
    'manual_ch_getting_started_s5' => 'ওপরের ভাষা বাটন দিয়ে বাংলা বা ইংরেজি বেছে নিন এবং দিনের বা রাতের মোড পছন্দমতো সেট করুন।',
    'manual_ch_getting_started_s6' => 'কোনো অংশ খোলার সময় "আগে এই ধাপগুলো শেষ করুন" বক্স দেখালে, সেখানে দেখানো কাজগুলো (যেমন প্রোফাইল পূরণ বা পেমেন্ট যাচাই) আগে শেষ করে আবার চেষ্টা করুন।',
    'manual_ch_getting_started_out1' => 'আপনি নিরাপদে লগইন হন এবং আপনার পদ অনুযায়ী অনুমোদিত অপশনসহ ড্যাশবোর্ড খোলে।',
    'manual_ch_getting_started_out2' => 'ড্যাশবোর্ডের টাকার কার্ডগুলো কোম্পানির হিসাব খাতা থেকে সঙ্গে সঙ্গে আপডেট হয়ে সর্বশেষ তথ্য দেখায়।',
    'manual_ch_getting_started_out3' => 'আপনার লগইন, আইপি ঠিকানা ও ডিভাইসের তথ্য কাজের রেকর্ডে রাখা হয়।',
    'manual_ch_getting_started_rule1' => 'শুধু নিজের বিশ্বস্ত ডিভাইস থেকে লগইন করুন। একই সময়ে একাধিক জায়গা থেকে সন্দেহজনক লগইন হলে সিস্টেম আপনা থেকে নিরাপত্তা যাচাইয়ের জন্য চিহ্ন দেয়।',
    'manual_ch_getting_started_rule2' => 'অ্যাকাউন্টের ধরন (ডিলার বা সাব-ডিলার) শুধু কোম্পানির ম্যানেজমেন্ট বদলাতে পারে।',
    'manual_ch_getting_started_rule3' => 'কোনো ডিলার বা সাব-ডিলারের অ্যাকাউন্ট বন্ধ বা স্থগিত থাকলে অর্ডার দেওয়া ও ওয়ালেট থেকে টাকা তোলা বন্ধ থাকবে।',
    'manual_ch_getting_started_t1' => 'প্রথম লগইনের ট্যুর বাদ দিলে, মেনুর "ব্যবহার নির্দেশিকা ও সাপোর্ট" থেকে যেকোনো সময় আবার চালু করতে পারবেন।',
    'manual_ch_getting_started_t2' => 'মোবাইল বা ট্যাবলেটে ওপরের বাম দিকের তিন দাগের মেনু বাটনে চাপ দিয়ে পুরো মেনু খুলুন।',
    'manual_ch_getting_started_warn1' => 'আপনার পাসওয়ার্ড বা OTP কখনো কাউকে দেবেন না—কোম্পানির কর্মকর্তা বা কর্মচারীকেও না।',
    'manual_ch_getting_started_warn2' => 'সাইবার ক্যাফে বা অন্যের ডিভাইসে লগইন করলে কাজ শেষে অবশ্যই প্রোফাইল মেনু থেকে "লগ আউট" করুন।',
    'manual_ch_getting_started_q1' => 'পাসওয়ার্ড ভুলে গেলে কীভাবে আবার লগইন করব?',
    'manual_ch_getting_started_a1' => 'লগইন পাতায় "পাসওয়ার্ড ভুলে গেছেন?" লিংকে চাপুন, নিবন্ধিত ফোন নম্বর দিন, তারপর এসএমএসে আসা OTP দিয়ে নতুন পাসওয়ার্ড সেট করুন।',
    'manual_ch_getting_started_q2' => 'ড্যাশবোর্ডের ব্যালেন্স ও তথ্য কি সঙ্গে সঙ্গে আপডেট হয়?',
    'manual_ch_getting_started_a2' => 'হ্যাঁ। প্রতিটি অর্ডার অনুমোদন, পেমেন্ট যাচাই বা কমিশন যোগ হলেই ড্যাশবোর্ড ও হিসাব খাতা সঙ্গে সঙ্গে আপডেট হয়।',
    // Chapter 2: profile_security
    'manual_ch_profile_security_title' => '২. প্রোফাইল, ডিজিটাল আইডি কার্ড ও দোকান যাচাই',
    'manual_ch_profile_security_badge' => 'প্রোফাইল ও পরিচয়পত্র',
    'manual_ch_profile_security_summary' => 'ব্যক্তিগত ও ব্যবসার পরিচয়, দোকানের ঠিকানা, NID/জন্ম নিবন্ধন যাচাই, অফিসিয়াল পার্টনার আইডি কার্ড এবং প্রচারের পোস্টার ডাউনলোডের নিয়ম।',
    'manual_ch_profile_security_purpose' => 'প্রোফাইল হলো আপনার পরিচয় (NID বা জন্ম নিবন্ধন), দোকানের ঠিকানা ও টাকার কাজে ব্যবহৃত ফোন নম্বরের মূল রেকর্ড। এই তথ্য দিয়েই কোম্পানি আপনার অফিসিয়াল ডিজিটাল আইডি কার্ড ও কিউআর কোডসহ পোস্টার তৈরি করে।',
    'manual_ch_profile_security_why' => 'আইন অনুযায়ী NID যাচাই ও মানি লন্ডারিং প্রতিরোধের নিয়ম মানতে হয়। সঠিক তথ্য থাকলে এলাকা নিয়ে বিরোধ হয় না এবং পেমেন্ট আসল ডিলারের কাছেই পৌঁছায়। এতে পার্টনারের অফিসিয়াল স্বীকৃতিও নিশ্চিত হয়।',
    'manual_ch_profile_security_s1' => 'বাম মেনুর "অ্যাকাউন্ট" অংশ থেকে "আমার প্রোফাইল" খুলুন।',
    'manual_ch_profile_security_s2' => 'আপনার পুরো নাম, বিকল্প ফোন নম্বর, ইমেইল, NID নম্বর ও দোকানের পুরো ঠিকানা ঠিকভাবে পূরণ করুন।',
    'manual_ch_profile_security_s3' => 'যাচাইয়ের জন্য একটি পরিষ্কার পাসপোর্ট সাইজ ছবি ও দোকানের সাইনবোর্ডের ছবি আপলোড করুন।',
    'manual_ch_profile_security_s4' => 'তথ্য রাখতে সেভ বাটনে চাপুন; সেভ হলে সবুজ বার্তা দেখাবে।',
    'manual_ch_profile_security_s5' => 'প্রোফাইল পাতার নিচে গিয়ে আইডি কার্ড ডাউনলোড বাটনে চাপুন; অফিসিয়াল আইডি কার্ড পিডিএফ আকারে নামবে।',
    'manual_ch_profile_security_s6' => 'জয়েন পোস্টার বাটনে চাপুন; আপনার নিজের রেফার কিউআর কোডসহ প্রিন্ট করার মতো পোস্টার পাবেন।',
    'manual_ch_profile_security_out1' => 'আপনার প্রোফাইল আপডেট হয় এবং অ্যাকাউন্টের অবস্থা "NID যাচাই হয়েছে" দেখায়।',
    'manual_ch_profile_security_out2' => 'আপনার কিউআর কোড, প্লেস কোড ও রেজিস্ট্রেশন নম্বরসহ অফিসিয়াল আইডি কার্ড PDF তৈরি হয়।',
    'manual_ch_profile_security_out3' => 'জয়েন পোস্টারের কিউআর কোডে আপনার রেফার লিংক থাকে; স্ক্যান করলেই আপনার টিমের অধীনে যোগ দেওয়ার পাতা খোলে।',
    'manual_ch_profile_security_rule1' => 'নিবন্ধিত মোবাইল নম্বর শুধু কোম্পানি অফিস যাচাই করে অনুমোদন দিলে বদলানো যায়।',
    'manual_ch_profile_security_rule2' => 'একই NID বা জন্ম নিবন্ধন নম্বর দিয়ে একাধিক ডিলারশিপ খোলা যাবে না।',
    'manual_ch_profile_security_rule3' => 'দোকান অন্য উপজেলায় সরালে সাপোর্ট অনুরোধ পাঠিয়ে প্লেস কোড বদলানোর আবেদন করতে হবে।',
    'manual_ch_profile_security_t1' => 'ডাউনলোড করা পার্টনার আইডি কার্ড প্রিন্ট ও লেমিনেট করে দোকানে ঝুলিয়ে রাখুন; এতে ক্রেতাদের আস্থা বাড়ে।',
    'manual_ch_profile_security_t2' => 'জয়েন পোস্টারটি ফেসবুকসহ সোশ্যাল মিডিয়ায় শেয়ার করুন, যাতে নতুন সাব-ডিলার আপনার কিউআর কোড স্ক্যান করে যোগ দিতে পারেন।',
    'manual_ch_profile_security_warn1' => 'ভুয়া বা অন্যের NID দিলে আইডি কার্ড বাতিলসহ অ্যাকাউন্ট স্থায়ীভাবে বন্ধ করা হবে।',
    'manual_ch_profile_security_warn2' => 'আইডি কার্ডে ফটোশপ বা কোনো রকম পরিবর্তন করা দণ্ডনীয় অপরাধ।',
    'manual_ch_profile_security_q1' => 'আমি কি আমার দোকানের নাম বা ঠিকানা পরিবর্তন করতে পারি?',
    'manual_ch_profile_security_a1' => 'হ্যাঁ, প্রোফাইল পাতা থেকে দোকানের নাম ও ঠিকানা বদলানো যায়। তবে ইউনিয়ন বা উপজেলা বদলালে প্লেস কোডও বদলাতে হবে—সাপোর্টে জানান।',
    'manual_ch_profile_security_q2' => 'আইডি কার্ড ডাউনলোড না হলে কী করব?',
    'manual_ch_profile_security_a2' => 'প্রোফাইলে নাম, ফোন ও ঠিকানা পূরণ করা আছে কিনা দেখুন। তথ্য অসম্পূর্ণ থাকলে আইডি কার্ড তৈরি হয় না।',
    // Chapter 3: catalog_orders
    'manual_ch_catalog_orders_title' => '৩. পণ্য তালিকা, পাইকারি কেনা ও অর্ডার',
    'manual_ch_catalog_orders_badge' => 'পণ্য ও কেনাকাটা',
    'manual_ch_catalog_orders_summary' => 'পাইকারি দাম ও MRP অনুযায়ী লাভ দেখা, পণ্য বাছাই, কার্টে যোগ, অর্ডার পাঠানো ও ইনভয়েস পাওয়ার নিয়ম।',
    'manual_ch_catalog_orders_purpose' => 'এখান থেকেই ডিলার ও সাব-ডিলাররা পাইকারি দামে পণ্য কেনেন। প্রতিটি পণ্যের সর্বোচ্চ খুচরা মূল্য (MRP) ও আপনার কেনা দাম পাশাপাশি দেখায়, তাই লাভ সহজে বোঝা যায়। কার্টে একাধিক পণ্য যোগ করে একটি অর্ডারে পাঠানো যায়।',
    'manual_ch_catalog_orders_why' => 'মধ্যস্বত্বভোগী ছাড়াই সরাসরি কোম্পানি থেকে আসল ন্যাচারাল কেয়ার পণ্য পাইকারি দামে কেনা যায়, তাই লাভ বেশি থাকে। প্রতিটি কেনার সঙ্গে সঙ্গে চালান ও ইনভয়েস তৈরি হয়।',
    'manual_ch_catalog_orders_s1' => 'বাম মেনু থেকে "পণ্য তালিকা" খুলুন।',
    'manual_ch_catalog_orders_s2' => 'প্রতিটি পণ্যের কার্ডে ছবি, বিবরণ, স্টক, সর্বোচ্চ খুচরা মূল্য (MRP), আপনার পাইকারি কেনা দাম ও সম্ভাব্য লাভ দেখুন।',
    'manual_ch_catalog_orders_s3' => 'প্রয়োজনীয় পণ্যের পরিমাণ বেছে "কার্টে যোগ করুন" বাটনে চাপুন।',
    'manual_ch_catalog_orders_s4' => 'কার্ট বারে চাপ দিয়ে বাছাই করা পণ্য, ছাড় ও মোট টাকার পরিমাণ মিলিয়ে নিন।',
    'manual_ch_catalog_orders_s5' => '"চেকআউটে যান" বা অর্ডার জমার বাটনে চাপ দিয়ে অনুরোধটি চূড়ান্ত করুন। দুবার চাপলেও দুটি অর্ডার হবে না।',
    'manual_ch_catalog_orders_s6' => 'অর্ডার পাঠানোর পর "অর্ডার" অংশে আপনার অর্ডার নম্বর (যেমন: ORD-2026-XXXX) ও অবস্থা "অপেক্ষমাণ" দেখতে পাবেন।',
    'manual_ch_catalog_orders_s7' => 'অর্ডারটি খুলে পণ্যগুলো দেখুন এবং খসড়া ইনভয়েস পিডিএফ ডাউনলোড করুন। আপনার কপিতে "ডিলার কপি" বা "সাব-ডিলার কপি" ওয়াটারমার্ক থাকে।',
    'manual_ch_catalog_orders_out1' => 'নতুন অর্ডার সেভ হয়। একই অর্ডার দুবার জমা পড়া সিস্টেম আটকে দেয়।',
    'manual_ch_catalog_orders_out2' => 'অর্ডারের মোট টাকা ও বাকি টাকা আপনা থেকে "বকেয়া" খাতায় ওঠে এবং পেমেন্ট যাচাই না হওয়া পর্যন্ত থাকে।',
    'manual_ch_catalog_orders_out3' => 'নতুন অর্ডার যাচাই ও স্টক আলাদা রাখার জন্য হিসাব ও ডেলিভারি টিমের ড্যাশবোর্ডে সঙ্গে সঙ্গে নোটিফিকেশন যায়।',
    'manual_ch_catalog_orders_rule1' => 'গুদামে যত স্টক আছে, তার বেশি অর্ডার দেওয়া যাবে না।',
    'manual_ch_catalog_orders_rule2' => 'অর্ডার পাঠানোর পর আর বদলানো বা মুছে ফেলা যায় না; বদলাতে হলে সাপোর্টের মাধ্যমে কোম্পানির ডেস্কে যোগাযোগ করে বাতিল করাতে হবে।',
    'manual_ch_catalog_orders_rule3' => 'আপনার স্তরের পাইকারি ছাড় কোম্পানির চালু নিয়ম অনুযায়ী প্রতিটি অর্ডারে আপনা থেকে বসে যায়।',
    'manual_ch_catalog_orders_t1' => 'মোবাইলে অর্ডার করার সময় নিচের কার্ট বার ব্যবহার করে দ্রুত চেকআউট করুন।',
    'manual_ch_catalog_orders_t2' => 'প্রতিটি পণ্যের MRP ও আপনার পাইকারি দামের পার্থক্য দেখে দোকানের লাভ হিসাব করুন।',
    'manual_ch_catalog_orders_warn1' => 'একই অর্ডারের জন্য বারবার সাবমিট বাটনে চাপবেন না; সিস্টেম নিজেই ডবল অর্ডার আটকায়, একটু অপেক্ষা করুন।',
    'manual_ch_catalog_orders_warn2' => 'গুদাম থেকে মাল পাঠানো নিশ্চিত না হওয়া পর্যন্ত ক্রেতাকে ডেলিভারির তারিখের কথা দেবেন না।',
    'manual_ch_catalog_orders_q1' => 'ইনভয়েস কপিতে ওয়াটারমার্ক কেন থাকে?',
    'manual_ch_catalog_orders_a1' => 'ডিলার ও সাব-ডিলারের কপিতে হালকা "ডিলার কপি" বা "সাব-ডিলার কপি" ওয়াটারমার্ক থাকে, যাতে আপনার কপি কোম্পানির নিজস্ব অফিস কপির সাথে গুলিয়ে না যায়।',
    'manual_ch_catalog_orders_q2' => 'পণ্য তালিকায় কোনো পণ্য "স্টক নেই" দেখালে কী করব?',
    'manual_ch_catalog_orders_a2' => 'সাপোর্টে অনুরোধ পাঠিয়ে গুদামে নতুন মাল কবে আসবে জেনে নিন। স্টকে এলেই আবার অর্ডার দেওয়া যাবে।',
    // Chapter 4: deliveries_dues
    'manual_ch_deliveries_dues_title' => '৪. ডেলিভারি ট্র্যাকিং, কুরিয়ার চালান ও বকেয়া হিসাব',
    'manual_ch_deliveries_dues_badge' => 'ডেলিভারি ও বকেয়া',
    'manual_ch_deliveries_dues_summary' => 'অনুমোদিত অর্ডার পাঠানো, কুরিয়ার ট্র্যাকিং (Steadfast, Pathao, RedX), ডেলিভারি নিশ্চিত করা এবং বাকি টাকার হিসাব।',
    'manual_ch_deliveries_dues_purpose' => 'এই অংশে গুদাম থেকে মাল পাঠানো, কুরিয়ারের ট্র্যাকিং নম্বর ও পার্সেলের অবস্থা, এবং পেমেন্ট যাচাইয়ের পর প্রতিটি অর্ডারে কত টাকা বাকি আছে—সব হিসাব থাকে।',
    'manual_ch_deliveries_dues_why' => 'কুরিয়ার ট্র্যাকিং দেরি ও মাল হারানো ঠেকাতে সাহায্য করে। আংশিক পেমেন্ট অর্ডারের সাথে মিলিয়ে বকেয়া শূন্য রাখলে আপনার ক্রেডিট পরিষ্কার থাকে এবং ব্যবসা ঠিকমতো চলে।',
    'manual_ch_deliveries_dues_s1' => 'মেনু থেকে "ডেলিভারি" খুলে পাঠানো অর্ডারের অবস্থা দেখুন।',
    'manual_ch_deliveries_dues_s2' => 'কুরিয়ারের নাম (যেমন: Steadfast, Pathao, RedX) ও ট্র্যাকিং কোড দেখতে পাবেন।',
    'manual_ch_deliveries_dues_s3' => 'ট্র্যাকিং লিংকে চাপ দিয়ে কুরিয়ারের ওয়েবসাইটে পার্সেল এখন কোথায় আছে দেখুন।',
    'manual_ch_deliveries_dues_s4' => 'পণ্য হাতে পৌঁছালে পার্সেলের সিল অক্ষত আছে কিনা পরীক্ষা করে ডেলিভারি চালানে স্বাক্ষর করুন।',
    'manual_ch_deliveries_dues_s5' => 'বকেয়া দেখতে মেনু থেকে "বকেয়া" অংশে যান; এখানে মোট কেনা, পরিশোধ করা টাকা ও বাকি টাকা দেখা যাবে।',
    'manual_ch_deliveries_dues_s6' => 'বকেয়া শোধ করতে অর্ডারটি খুলে বিকাশ/নগদ/ব্যাংকে টাকা পাঠান এবং TrxID দিয়ে পেমেন্ট দাবি জমা দিন।',
    'manual_ch_deliveries_dues_out1' => 'অর্ডারের অবস্থা "পাঠানো হয়েছে" থেকে "ডেলিভারি হয়েছে"-তে বদলায় এবং চালানের প্রমাণ সিস্টেমে রাখা হয়।',
    'manual_ch_deliveries_dues_out2' => 'হিসাব বিভাগ পেমেন্ট অনুমোদন করলে অর্ডারের বকেয়া শূন্য (৳0.00) হয়।',
    'manual_ch_deliveries_dues_out3' => 'ডিলারের টাকার হিসাব পরিষ্কার থাকে এবং পরের বড় অর্ডারে ক্রেডিট পাওয়া সহজ হয়।',
    'manual_ch_deliveries_dues_rule1' => 'শুধু পেমেন্ট যাচাই হওয়া বা অনুমোদিত ক্রেডিট সীমার মধ্যে থাকা অর্ডারই পাঠানোর জন্য প্যাক করা হয়।',
    'manual_ch_deliveries_dues_rule2' => 'কুরিয়ারে মাল নষ্ট হলে পার্সেল নেবেন না বা চালানে নোট লিখুন, এবং ছবি তুলে সাপোর্টে জানান।',
    'manual_ch_deliveries_dues_rule3' => 'বকেয়া শোধের দাবির সাথে অবশ্যই সঠিক TrxID বা ব্যাংকে জমার রসিদ দিতে হবে।',
    'manual_ch_deliveries_dues_t1' => 'ডেলিভারি চালানের কপি বা ছবি দোকানে রেখে দিন; পরে হিসাব মেলাতে বা গরমিল হলে কাজে লাগবে।',
    'manual_ch_deliveries_dues_t2' => 'নিয়মিত "বকেয়া" অংশ দেখুন, যাতে কোনো অর্ডারের টাকা জমে না থাকে এবং পেমেন্ট আটকে না যায়।',
    'manual_ch_deliveries_dues_warn1' => 'সিল ছেঁড়া বা নষ্ট প্যাকেট নেবেন না; খোলা সিলের প্যাকেট নিলে কোম্পানি দায়ী থাকবে না।',
    'manual_ch_deliveries_dues_warn2' => 'ভুয়া TrxID দিয়ে বকেয়া শোধের দাবি করা প্রতারণা; এতে অ্যাকাউন্ট সঙ্গে সঙ্গে বন্ধ করা হতে পারে।',
    'manual_ch_deliveries_dues_q1' => 'কুরিয়ার ডেলিভারি দেরি হলে কী করব?',
    'manual_ch_deliveries_dues_a1' => '"ডেলিভারি" পাতার ট্র্যাকিং নম্বর দিয়ে কুরিয়ারের সাইটে অবস্থা দেখুন, অথবা অর্ডার নম্বর লিখে সাপোর্ট অনুরোধ পাঠান।',
    'manual_ch_deliveries_dues_q2' => 'আমি পেমেন্ট করেছি, তবু "বকেয়া" অংশে টাকা বাকি দেখাচ্ছে কেন?',
    'manual_ch_deliveries_dues_a2' => 'পেমেন্ট দাবি জমার পর হিসাব বিভাগ ব্যাংক স্টেটমেন্টের সাথে মিলিয়ে অনুমোদন দিলে বকেয়া শূন্য হবে। এতে সাধারণত অফিস সময়ের ১-৩ ঘণ্টা লাগে।',
    // Chapter 5: network_genealogy
    'manual_ch_network_genealogy_title' => '৫. রেফার নেটওয়ার্ক, টিম ট্রি ও আপনার নিচের টিম',
    'manual_ch_network_genealogy_badge' => 'রেফার ও টিম',
    'manual_ch_network_genealogy_summary' => 'জয়েন লিংক ও কিউআর পোস্টার শেয়ার, স্তর অনুযায়ী নিচের টিমের ট্রি দেখা এবং টিমের বিক্রি দেখা।',
    'manual_ch_network_genealogy_purpose' => 'নেটওয়ার্ক অংশে আপনার টিম গাছের মতো সাজানো দেখা যায়, যাতে নিজের বিক্রির টিম গড়তে ও বড় করতে পারেন। কে কাকে স্পন্সর করেছেন, কে কোন স্তরে আছেন এবং টিমের মোট কেনাকাটা কত—সব এখানে দেখা যায়।',
    'manual_ch_network_genealogy_why' => 'শক্তিশালী টিম গড়লে টিম কমিশন ও র‍্যাঙ্ক বোনাস পাওয়া যায়। টিমের সদস্যদের অগ্রগতি দেখে তাদের উৎসাহ দিতে এবং দুর্বল এলাকায় বিক্রি বাড়াতে পারবেন।',
    'manual_ch_network_genealogy_s1' => 'মেনু থেকে "আমার নেটওয়ার্ক" খুলুন।',
    'manual_ch_network_genealogy_s2' => 'রেফার লিংক কপির বাটনে চাপুন অথবা আপনার রেফার কোডসহ জয়েন পোস্টার ডাউনলোড করুন।',
    'manual_ch_network_genealogy_s3' => 'নতুন পার্টনারকে এই লিংক দিয়ে রেজিস্ট্রেশন করতে বলুন; তারা আপনা থেকে আপনার টিমে যুক্ত হবেন এবং আপনি হবেন তাদের সরাসরি স্পন্সর।',
    'manual_ch_network_genealogy_s4' => 'টিম ট্রি ট্যাবে চাপ দিয়ে আপনার নিচের টিমের ছবি দেখুন, যেখানে প্রতিটি স্তরের পার্টনার কোথায় আছেন বোঝা যায়।',
    'manual_ch_network_genealogy_s5' => 'যেকোনো সদস্যের ওপর চাপ দিয়ে তার নাম, ফোন, যোগদানের তারিখ, বর্তমান র‍্যাঙ্ক এবং নিজের ও টিমের বিক্রি দেখুন।',
    'manual_ch_network_genealogy_s6' => 'পুরো টিমের তালিকা অফলাইনে রাখতে এক্সপোর্ট (CSV) বাটনে চাপ দিয়ে এক্সেল ফাইলে সেভ করুন।',
    'manual_ch_network_genealogy_out1' => 'নতুন পার্টনার রেজিস্ট্রেশন করলে তিনি আপনার রেফার ট্রিতে যুক্ত হন।',
    'manual_ch_network_genealogy_out2' => 'নিচের টিমের যেকোনো সদস্যের কেনাকাটা অনুমোদিত হওয়া মাত্রই স্পন্সর হিসেবে আপনার ওয়ালেটে রেফার কমিশন যোগ হয়।',
    'manual_ch_network_genealogy_out3' => 'টিমের মোট বিক্রি আপনার র‍্যাঙ্ক ও রিওয়ার্ড টার্গেট পূরণে যোগ হতে থাকে।',
    'manual_ch_network_genealogy_rule1' => 'একবার কোনো পার্টনার স্পন্সর কোড দিয়ে নিবন্ধিত হলে পরে আর অন্য স্পন্সরের অধীনে নেওয়া যায় না।',
    'manual_ch_network_genealogy_rule2' => 'রেফার কমিশন পেতে স্পন্সরের অ্যাকাউন্ট সক্রিয় রাখতে হবে এবং মাসিক ন্যূনতম কেনাকাটা বজায় রাখতে হবে।',
    'manual_ch_network_genealogy_rule3' => 'মিথ্যা প্রলোভন বা ভুল তথ্য দিয়ে ডিলার যুক্ত করা কোম্পানির নিয়মের বিরুদ্ধে; এতে সঙ্গে সঙ্গে তদন্ত হবে।',
    'manual_ch_network_genealogy_t1' => 'আপনার সরাসরি স্পন্সর করা ডিলারদের সাথে নিয়মিত যোগাযোগ রাখুন এবং পণ্য সম্পর্কে শেখান।',
    'manual_ch_network_genealogy_t2' => 'টিমের সক্রিয় সদস্যদের পরের র‍্যাঙ্ক পেতে সাহায্য করুন; এতে র‍্যাঙ্ক বোনাস ফান্ডে আপনার ভাগও বাড়বে।',
    'manual_ch_network_genealogy_warn1' => 'সোশ্যাল মিডিয়ায় আয়ের মিথ্যা প্রতিশ্রুতি বা বিভ্রান্তিকর বিজ্ঞাপন দেওয়া নিষিদ্ধ।',
    'manual_ch_network_genealogy_warn2' => 'স্পন্সর ছাড়া রেজিস্ট্রেশন করলে কোম্পানি তাকে ওই এলাকার এরিয়া ডিলারের অধীনে যুক্ত করতে পারে।',
    'manual_ch_network_genealogy_q1' => 'আমার নিচের টিমের কেউ কেনাকাটা করলে আমি কীভাবে জানব?',
    'manual_ch_network_genealogy_a1' => 'তাদের কেনাকাটা অনুমোদিত হলেই "আমার আয়" অংশে ওই অর্ডার নম্বর ও আপনার কমিশনের এন্ট্রি সঙ্গে সঙ্গে দেখা যাবে।',
    'manual_ch_network_genealogy_q2' => 'টিম ট্রিতে কত স্তর পর্যন্ত দেখা যায়?',
    'manual_ch_network_genealogy_a2' => 'কোনো সীমা নেই। প্রথম স্তর থেকে নিচের সব স্তর পর্যন্ত স্ক্রল বা জুম করে দেখা যায়।',
    // Chapter 6: area_dealers_places
    'manual_ch_area_dealers_places_title' => '৬. প্লেস কোড, এরিয়া ডিলার ও নিজস্ব এলাকা',
    'manual_ch_area_dealers_places_badge' => 'নিজস্ব এলাকা',
    'manual_ch_area_dealers_places_summary' => 'বিভাগ, জেলা, উপজেলা ও ইউনিয়নভিত্তিক ৬ সংখ্যার প্লেস কোড, এরিয়া ডিলারের বিশেষ সুবিধা এবং এলাকা সুরক্ষা।',
    'manual_ch_area_dealers_places_purpose' => 'প্লেস কোড দিয়ে সারা বাংলাদেশকে (বিভাগ > জেলা > উপজেলা > ইউনিয়ন) আলাদা আলাদা কোডে ভাগ করা হয়েছে। এই কোড দিয়েই প্রতিটি এরিয়া ডিলারের নিজস্ব এলাকা ঠিক করা হয়।',
    'manual_ch_area_dealers_places_why' => 'একই এলাকায় ডিলারদের মধ্যে অযথা প্রতিযোগিতা বন্ধ হয় এবং প্রতিটি এলাকায় নিয়ম মেনে পণ্য পৌঁছায়। এরিয়া ডিলাররা তাদের এলাকার সব স্থানীয় বিক্রির ওপর বিশেষ কমিশন পান।',
    'manual_ch_area_dealers_places_s1' => 'মেনুর "এরিয়া ডিলার" তালিকা অথবা প্রোফাইল থেকে আপনার প্লেস কোড দেখুন।',
    'manual_ch_area_dealers_places_s2' => 'প্লেস কোডের প্রথম ২ সংখ্যা বিভাগ, পরবর্তী ২ সংখ্যা জেলা এবং শেষ ২ সংখ্যা উপজেলা/থানা নির্দেশ করে।',
    'manual_ch_area_dealers_places_s3' => 'আপনার ইউনিয়ন বা উপজেলার জন্য কোনো এরিয়া ডিলার নির্ধারিত আছে কিনা তা দেখতে প্লেস কোড তালিকা সার্চ করুন।',
    'manual_ch_area_dealers_places_s4' => 'নির্দিষ্ট উপজেলার একমাত্র এরিয়া ডিলার হতে চাইলে নির্ধারিত বিনিয়োগ ও বিক্রির শর্ত পূরণ করে ম্যানেজমেন্টের কাছে আবেদন করুন।',
    'manual_ch_area_dealers_places_s5' => 'এরিয়া ডিলার হলে আপনার এলাকার সাব-ডিলারদের অর্ডারের সরবরাহ ও ডেলিভারিতে আপনি অগ্রাধিকার পাবেন এবং তাদের বিক্রিতে লাভের ভাগ পাবেন।',
    'manual_ch_area_dealers_places_s6' => 'এলাকা নিয়ে বিরোধ হলে বা দোকান সরালে সাপোর্ট অনুরোধ পাঠান; প্লেস কোডের রেকর্ড দেখে সমাধান করা হবে।',
    'manual_ch_area_dealers_places_out1' => 'আপনার অ্যাকাউন্ট প্লেস কোডের সাথে যুক্ত হয় এবং সেই এলাকার অর্ডারে এলাকার অগ্রাধিকার চালু হয়।',
    'manual_ch_area_dealers_places_out2' => 'ওই প্লেস কোডের সাব-ডিলারদের কেনাকাটা আপনা থেকে এরিয়া ডিলারের হিসাবে যুক্ত হয়।',
    'manual_ch_area_dealers_places_out3' => 'ডিলার তালিকায় আপনার দোকান ওই উপজেলার অফিসিয়াল ডিস্ট্রিবিউশন পয়েন্ট হিসেবে দেখায়।',
    'manual_ch_area_dealers_places_rule1' => 'কোম্পানির নিয়ম অনুযায়ী প্রতিটি উপজেলা বা থানায় সীমিত সংখ্যক এরিয়া ডিলার রাখা হয়।',
    'manual_ch_area_dealers_places_rule2' => 'এরিয়া ডিলারশিপ ধরে রাখতে প্রতি মাসে আপনার এলাকায় নির্ধারিত ন্যূনতম বিক্রি করতে হবে।',
    'manual_ch_area_dealers_places_rule3' => 'অনুমতি ছাড়া অন্য ডিলারের এলাকায় গিয়ে পাইকারি মাল দেওয়া শৃঙ্খলাভঙ্গ; এর জন্য ব্যবস্থা নেওয়া হবে।',
    'manual_ch_area_dealers_places_t1' => 'আপনার উপজেলার দোকানদার, ফার্মেসি ও সাব-ডিলারদের সাথে ভালো সম্পর্ক রাখুন, যাতে তারা নিয়মিত আপনার কাছ থেকেই মাল নেন।',
    'manual_ch_area_dealers_places_t2' => 'নতুন কাউকে যুক্ত করার সময় তার দোকানের সাথে মেলে এমন সঠিক প্লেস কোড বেছে নেওয়া হয়েছে কিনা দেখুন।',
    'manual_ch_area_dealers_places_warn1' => 'ভুল প্লেস কোড দিলে আপনার কমিশন ও ডেলিভারি ভুল এলাকায় চলে যেতে পারে।',
    'manual_ch_area_dealers_places_warn2' => 'টানা তিন মাস টার্গেট পূরণ না হলে কোম্পানি ওই এলাকার এরিয়া ডিলারশিপ অন্য যোগ্য ডিলারকে দিতে পারে।',
    'manual_ch_area_dealers_places_q1' => 'আমি কীভাবে আমার প্লেস কোড জানতে পারব?',
    'manual_ch_area_dealers_places_a1' => 'আপনার প্রোফাইল পাতায় ও আইডি কার্ডের নিচের অংশে ৬ সংখ্যার প্লেস কোড লেখা আছে।',
    'manual_ch_area_dealers_places_q2' => 'একই উপজেলায় কি একাধিক এরিয়া ডিলার থাকতে পারে?',
    'manual_ch_area_dealers_places_a2' => 'বড় উপজেলায় ইউনিয়ন ভিত্তিক একাধিক ডিলার থাকতে পারেন, তবে একটি ইউনিয়নের জন্য একজন ডিলারই থাকেন।',
    // Chapter 7: commissions_pool
    'manual_ch_commissions_pool_title' => '৭. কমিশন কীভাবে কাজ করে, ৪০/৬০ ভাগ ও লাইভ আয়ের খাতা',
    'manual_ch_commissions_pool_badge' => 'কমিশন ও টাকা',
    'manual_ch_commissions_pool_summary' => 'কোম্পানির ৪০% পার্টনার কমিশন ফান্ড ও ৬০% কোম্পানির ভাগ, রেফার বোনাস, স্তর কমিশন এবং প্রতিটি হিসাবের প্রমাণ।',
    'manual_ch_commissions_pool_purpose' => 'প্রতিটি অনুমোদিত অর্ডারের টাকা ৪০/৬০ ভাগে ভাগ হয়: ৬০% কোম্পানির উৎপাদন ও চালানোর খরচের জন্য থাকে, আর ৪০% পার্টনার কমিশন ফান্ডে যায় এবং রেফার, স্তর ও র‍্যাঙ্ক বোনাস হিসেবে দেওয়া হয়।',
    'manual_ch_commissions_pool_why' => 'ব্যবসা স্বচ্ছ ও প্রতারণামুক্ত রাখতে এই হিসাব মানা হয়। কোনো ভুয়া বা কাল্পনিক টাকা দেওয়া হয় না; শুধু আসল বিক্রি থেকে আসা লাভই আপনা থেকে খাতায় জমা হয় এবং তা তোলা যায়।',
    'manual_ch_commissions_pool_s1' => 'মেনু থেকে "আমার আয়" খুলে মোট কমিশন ও তোলার যোগ্য ব্যালেন্স দেখুন।',
    'manual_ch_commissions_pool_s2' => 'ব্যালেন্সের কার্ডে তিনটি অংশ দেখবেন: "তোলার যোগ্য ব্যালেন্স", "তোলা হয়েছে" (পরিশোধিত) এবং "অপেক্ষমাণ" (যাচাই চলছে)।',
    'manual_ch_commissions_pool_s3' => 'তারিখ ফিল্টার (আজ, এই সপ্তাহ, এই মাস বা নিজের পছন্দের তারিখ) দিয়ে নির্দিষ্ট সময়ের আয় দেখুন।',
    'manual_ch_commissions_pool_s4' => 'নিচের খাতার টেবিলে প্রতিটি আয়ের লাইন দেখুন: তারিখ, কমিশনের ধরন (সরাসরি রেফার, স্তর, র‍্যাঙ্ক, র‍্যাঙ্ক বোনাস), হার (%), ক্রেতা ও অর্ডার নম্বর।',
    'manual_ch_commissions_pool_s5' => 'যেকোনো এন্ট্রিতে চাপ দিলে কীভাবে হিসাব হয়েছে, কোন অর্ডার থেকে এসেছে ও কোন নিয়মে ভাগ হয়েছে—সব দেখা যাবে।',
    'manual_ch_commissions_pool_s6' => 'খাতায় যোগ হওয়া প্রতিটি টাকা সঙ্গে সঙ্গে আপনার তোলার যোগ্য ব্যালেন্সে আসে এবং তখনই তোলার অনুরোধ করা যায়।',
    'manual_ch_commissions_pool_out1' => 'অর্ডার মেলার সঙ্গে সঙ্গে হিসাবের দুই দিকেই এন্ট্রি লেখা হয়, যা পরে বদলানো যায় না।',
    'manual_ch_commissions_pool_out2' => 'আপনার ওয়ালেটের তোলার যোগ্য ব্যালেন্স বাড়ে এবং এসএমএস বা অ্যাপের নোটিফিকেশনে জানানো হয়।',
    'manual_ch_commissions_pool_out3' => 'কোম্পানির ৬০% ও পার্টনারের ৪০% ভাগের হিসাব সব সময় মিলে থাকে, কোনো গরমিল হয় না।',
    'manual_ch_commissions_pool_rule1' => 'মোট কমিশন কখনো কোম্পানির নির্ধারিত ৪০% ফান্ডের বেশি হবে না; সিস্টেম নিজেই এটা নিশ্চিত করে।',
    'manual_ch_commissions_pool_rule2' => 'বাতিল বা রিফান্ড হওয়া অর্ডারের কমিশন আপনা থেকে ফেরত এন্ট্রির মাধ্যমে সবার হিসাব থেকে কেটে নেওয়া হয়।',
    'manual_ch_commissions_pool_rule3' => 'টাকা না তোলা পর্যন্ত অর্জিত কমিশন আপনার ওয়ালেটে নিরাপদে থাকবে; এর কোনো মেয়াদ শেষ হয় না।',
    'manual_ch_commissions_pool_t1' => 'প্রতি সপ্তাহে বা মাস শেষে আয়ের স্টেটমেন্ট মিলিয়ে নিন, যাতে আপনার হিসাব পরিষ্কার থাকে এবং কোন পণ্য ভালো চলছে বোঝা যায়।',
    'manual_ch_commissions_pool_t2' => 'নিচের টিমের বড় অর্ডারের কমিশন এলে খাতার অর্ডার নম্বর দেখে বুঝুন টিমের কে ভালো করছেন, এবং তাকে উৎসাহ দিন।',
    'manual_ch_commissions_pool_warn1' => 'কোম্পানি আসল টাকার হিসাব চালু না করা এবং শুরুর ব্যালেন্স অনুমোদন না হওয়া পর্যন্ত কোনো টাকার হিসাব কার্যকর হবে না।',
    'manual_ch_commissions_pool_warn2' => 'খাতার কোনো তথ্য ভুল মনে হলে লেনদেনের নম্বর বা স্ক্রিনশটসহ সঙ্গে সঙ্গে সাপোর্টে জানান।',
    'manual_ch_commissions_pool_q1' => '৪০% ও ৬০% ভাগের হিসাব কীভাবে হয়?',
    'manual_ch_commissions_pool_a1' => 'যেকোনো পণ্যের বিক্রির টাকার ৬০% কোম্পানির কারখানা, কাঁচামাল ও চালানোর খরচে যায়, আর বাকি ৪০% ডিলার ও পার্টনারদের কমিশন হিসেবে ভাগ হয়।',
    'manual_ch_commissions_pool_q2' => 'কমিশন কি সঙ্গে সঙ্গে ওয়ালেটে যোগ হয়?',
    'manual_ch_commissions_pool_a2' => 'হ্যাঁ, হিসাব বিভাগ কোনো অর্ডারের পেমেন্ট যাচাই করে অনুমোদন দিলেই এক সেকেন্ডের মধ্যে কমিশন ওয়ালেটে জমা হয়।',
    // Chapter 8: ranks_royalties
    'manual_ch_ranks_royalties_title' => '৮. ডিলারের র‍্যাঙ্ক, মাসিক বিক্রির শর্ত ও র‍্যাঙ্ক বোনাস ফান্ড',
    'manual_ch_ranks_royalties_badge' => 'র‍্যাঙ্ক ও বোনাস',
    'manual_ch_ranks_royalties_summary' => 'মার্কেটিং অফিসার (MO) থেকে মার্কেটিং এক্সিকিউটিভ (ME) পর্যন্ত র‍্যাঙ্কের ধাপ, মাসিক নিজের ও টিমের বিক্রির টার্গেট এবং কোম্পানির মোট বিক্রি থেকে র‍্যাঙ্ক বোনাসের ভাগ।',
    'manual_ch_ranks_royalties_purpose' => 'র‍্যাঙ্ক ও র‍্যাঙ্ক বোনাস সফল ডিলারদের দীর্ঘমেয়াদি উন্নতি ও নিয়মিত আয়ের সুযোগ দেয়। নির্দিষ্ট র‍্যাঙ্ক অর্জন করলে ডিলাররা প্রতি মাসে কোম্পানির মোট মাসিক বিক্রির একটি নির্দিষ্ট অংশ র‍্যাঙ্ক বোনাস হিসেবে পান।',
    'manual_ch_ranks_royalties_why' => 'শুধু নিজের বিক্রির ওপর নির্ভর না করে শীর্ষ ডিলারদের কোম্পানির উন্নতির আসল অংশীদার করাই এর লক্ষ্য। এটি টিম গড়া ও নেতৃত্বের মূল্য দেয় এবং প্রতি মাসে র‍্যাঙ্ক বোনাস দেয়।',
    'manual_ch_ranks_royalties_s1' => 'মেনু থেকে "র‍্যাঙ্ক" অংশ খুলে আপনার বর্তমান র‍্যাঙ্ক এবং পরের র‍্যাঙ্কে পৌঁছানোর অগ্রগতি দেখুন।',
    'manual_ch_ranks_royalties_s2' => 'মূল র‍্যাঙ্কগুলো হলো: মার্কেটিং অফিসার (MO), অ্যাসিস্ট্যান্ট ম্যানেজার (AM), সেলস ম্যানেজার (SM) এবং মার্কেটিং এক্সিকিউটিভ (ME)।',
    'manual_ch_ranks_royalties_s3' => 'পরের র‍্যাঙ্কের জন্য নিজের কত কেনাকাটা (PV) এবং টিমের মোট কত কেনাকাটা (GV) লাগবে, তা দেখে নিন।',
    'manual_ch_ranks_royalties_s4' => 'আপনার টিমের সদস্যদের সক্রিয় রাখুন, যাতে তাদের বিক্রি আপনার র‍্যাঙ্কের শর্ত পূরণ করে।',
    'manual_ch_ranks_royalties_s5' => 'মাসিক শর্ত পূরণ হলে সিস্টেম আপনা থেকে আপনাকে নতুন র‍্যাঙ্ক দেবে এবং প্রোফাইলে নতুন ব্যাজ যুক্ত হবে।',
    'manual_ch_ranks_royalties_s6' => 'প্রতি মাসের ১ তারিখে কোম্পানির মোট বিক্রির ওপর র‍্যাঙ্ক বোনাস ফান্ড হিসাব করে আপনার ভাগ সরাসরি ওয়ালেটে জমা করা হবে।',
    'manual_ch_ranks_royalties_out1' => 'আপনার র‍্যাঙ্ক আপনা থেকে আপডেট হয় এবং তারিখসহ রেকর্ড রাখা হয়।',
    'manual_ch_ranks_royalties_out2' => 'মাসিক র‍্যাঙ্ক বোনাস ফান্ডের ভাগের তালিকায় আপনার নাম যুক্ত হয়।',
    'manual_ch_ranks_royalties_out3' => 'কোম্পানির লিডারবোর্ডে আপনার নাম আসে এবং বিশেষ সভায় সম্মান ও স্বীকৃতি দেওয়া হয়।',
    'manual_ch_ranks_royalties_rule1' => 'কোনো মাসে র‍্যাঙ্ক বোনাস পেতে সেই মাসে নিজের ন্যূনতম কেনাকাটা থাকতে হবে।',
    'manual_ch_ranks_royalties_rule2' => 'র‍্যাঙ্ক হিসাবে শুধু অনুমোদিত ও পুরো পরিশোধিত অর্ডার ধরা হয়; বাকি থাকা অর্ডার ধরা হয় না।',
    'manual_ch_ranks_royalties_rule3' => 'টানা কয়েক মাস শর্ত পূরণ না হলে গ্রেস পিরিয়ডের নিয়ম অনুযায়ী র‍্যাঙ্ক বোনাস আটকে যেতে পারে।',
    'manual_ch_ranks_royalties_t1' => 'মাসের ২০ তারিখের মধ্যেই আপনার ও আপনার টিমের পয়েন্ট চেক করুন, যাতে শেষ মুহূর্তে টার্গেট পূরণ করতে কোনো ঘাটতি না থাকে।',
    'manual_ch_ranks_royalties_t2' => 'নিচের টিমের অন্তত ২ জন লিডারকে র‍্যাঙ্ক পেতে সাহায্য করুন; এতে আপনার র‍্যাঙ্ক ধরে রাখা সহজ হয়।',
    'manual_ch_ranks_royalties_warn1' => 'নিজের আইডি দিয়ে ভুয়া কেনাকাটা বা বারবার অর্ডার বাতিল করে র‍্যাঙ্ক পাওয়ার চেষ্টা করলে সঙ্গে সঙ্গে র‍্যাঙ্ক বাতিল করা হবে।',
    'manual_ch_ranks_royalties_warn2' => 'র‍্যাঙ্ক বোনাস ফান্ডের টাকা পুরোপুরি কোম্পানির আসল বিক্রির ওপর নির্ভর করে; এটি কোনো নির্দিষ্ট বা বাঁধা মুনাফা নয়।',
    'manual_ch_ranks_royalties_q1' => 'আমি কখন পরের র‍্যাঙ্ক পাব?',
    'manual_ch_ranks_royalties_a1' => 'আপনার নিজের ও টিমের বিক্রির টার্গেট পূরণ হলেই সিস্টেম সঙ্গে সঙ্গে আপনার র‍্যাঙ্ক বাড়িয়ে দেয়।',
    'manual_ch_ranks_royalties_q2' => 'র‍্যাঙ্ক বোনাস টাকা মাসে কয়বার দেওয়া হয়?',
    'manual_ch_ranks_royalties_a2' => 'র‍্যাঙ্ক বোনাস প্রতি মাসের মোট বিক্রির ওপর হিসাব করা হয় এবং পরের মাসের প্রথম সপ্তাহে একবার সরাসরি ওয়ালেটে জমা হয়।',
    // Chapter 9: rewards_milestones
    'manual_ch_rewards_milestones_title' => '৯. টার্গেট পূরণের পুরস্কার: স্মার্টফোন, মোটরবাইক ও প্রাইভেট কার',
    'manual_ch_rewards_milestones_badge' => 'পুরস্কার',
    'manual_ch_rewards_milestones_summary' => 'দীর্ঘমেয়াদি মোট পয়েন্টের টার্গেট, মোটরবাইক ও কার পুরস্কারের আবেদন, সরেজমিন যাচাই এবং বার্ষিক পুরস্কার হস্তান্তরের নিয়ম।',
    'manual_ch_rewards_milestones_purpose' => 'পুরস্কার প্রোগ্রামে শীর্ষ পার্টনারদের সাফল্যের স্বীকৃতি হিসেবে স্মার্টফোন, ল্যাপটপ, মোটরবাইক ও প্রাইভেট কারের মতো আসল উপহার দেওয়া হয়। এটি দীর্ঘ সময়ের পরিশ্রমের সম্মান।',
    'manual_ch_rewards_milestones_why' => 'নগদ কমিশনের পাশাপাশি ডিলারদের জীবনযাত্রা উন্নত করতে ও সমাজে প্রতিষ্ঠিত করতে কোম্পানি এই পুরস্কার রাখে। এটি পার্টনার ও কোম্পানির দীর্ঘ সম্পর্কের প্রতীক।',
    'manual_ch_rewards_milestones_s1' => 'মেনু থেকে "পুরস্কার" বা "টার্গেট" অংশ খুলুন।',
    'manual_ch_rewards_milestones_s2' => 'পুরস্কারের স্তরগুলো দেখুন: লেভেল ১ (স্মার্ট ডিভাইস/ট্যাবলেট), লেভেল ২ (ল্যাপটপ), লেভেল ৩ (মোটরবাইক) এবং লেভেল ৪ (প্রাইভেট কার)।',
    'manual_ch_rewards_milestones_s3' => 'প্রতিটি পুরস্কারের জন্য মোট কত পয়েন্ট লাগবে আর আপনার এখন কত হয়েছে, তা দেখুন।',
    'manual_ch_rewards_milestones_s4' => 'পয়েন্ট ১০০% পূরণ হলে ওই পুরস্কারের কার্ডে আবেদনের বাটন চালু হবে।',
    'manual_ch_rewards_milestones_s5' => 'আবেদনের বাটনে চাপ দিয়ে আপনার NID, ড্রাইভিং লাইসেন্স (দরকার হলে) ও যোগাযোগের তথ্যসহ আবেদন জমা দিন।',
    'manual_ch_rewards_milestones_s6' => 'কোম্পানির যাচাই বোর্ড আবেদন যাচাই করে অনুমোদন দেবে, তারপর বার্ষিক অনুষ্ঠানে চাবি ও কাগজপত্র হাতে তুলে দেওয়া হবে।',
    'manual_ch_rewards_milestones_out1' => 'আপনার পুরস্কারের আবেদনের অবস্থা "যাচাইয়ের অপেক্ষায়" হয় এবং যাচাই বোর্ডে ফাইল তোলা হয়।',
    'manual_ch_rewards_milestones_out2' => 'অনুমোদনের পর ডিলারের পাবলিক প্রোফাইলে স্থায়ী পুরস্কারজয়ীর ব্যাজ যুক্ত হয়।',
    'manual_ch_rewards_milestones_out3' => 'গাড়ির রেজিস্ট্রেশন ও ডিলারের নামে মালিকানার সব কাগজপত্র কোম্পানি করে দেয়।',
    'manual_ch_rewards_milestones_rule1' => 'শুধু যাচাই হওয়া ও পুরো পরিশোধিত অর্ডার, যা রিফান্ড হয়নি, পুরস্কারের পয়েন্টে যোগ হয়।',
    'manual_ch_rewards_milestones_rule2' => 'রিওয়ার্ড পয়েন্ট কোনো অবস্থাতেই একজনের অ্যাকাউন্ট থেকে অন্যজনের অ্যাকাউন্টে নেওয়া যাবে না।',
    'manual_ch_rewards_milestones_rule3' => 'পুরস্কার পাওয়ার পর নির্দিষ্ট সময় ডিলারশিপ সক্রিয় রাখা ও সততার সাথে কোম্পানির প্রতিনিধিত্ব করার সম্মতিপত্রে সই করতে হয়।',
    'manual_ch_rewards_milestones_t1' => 'রিওয়ার্ড পয়েন্ট কখনো বাতিল হয় না বা মেয়াদ শেষ হয় না; ধৈর্য ধরে নিয়মিত কাজ করে যান।',
    'manual_ch_rewards_milestones_t2' => 'টিমের অন্যান্য সদস্যদের এই মাইলফলকগুলোর ব্যাপারে উৎসাহিত করুন যাতে তারা সম্মিলিতভাবে দ্রুত এগিয়ে যেতে পারে।',
    'manual_ch_rewards_milestones_warn1' => 'ভুয়া বা ঘুরিয়ে-ফিরিয়ে অর্ডার দিয়ে পয়েন্ট বাড়ানোর চেষ্টা ধরা পড়লে সব রিওয়ার্ড পয়েন্ট শূন্য করা হবে।',
    'manual_ch_rewards_milestones_warn2' => 'পুরস্কার কেনার আগে কোম্পানি প্রতিটি আবেদন ভালোভাবে যাচাই করে।',
    'manual_ch_rewards_milestones_q1' => 'বাইক বা কার রিওয়ার্ড কি নগদে নেওয়া যাবে?',
    'manual_ch_rewards_milestones_a1' => 'কোম্পানির নিয়মে আসল গাড়ি হস্তান্তরকেই অগ্রাধিকার দেওয়া হয়। বিশেষ ক্ষেত্রে ম্যানেজমেন্টের সাথে কথা বলুন; বোর্ড সিদ্ধান্ত নেবে।',
    'manual_ch_rewards_milestones_q2' => 'কমিশনের টাকা তুললে কি রিওয়ার্ড পয়েন্ট কমে যায়?',
    'manual_ch_rewards_milestones_a2' => 'না! কমিশনের টাকা তুললেও আপনার মোট রিওয়ার্ড পয়েন্ট একটুও বদলায় না।',
    // Chapter 10: subdealer_salary_tour
    'manual_ch_subdealer_salary_tour_title' => '১০. সাব-ডিলার প্ল্যান: কেনার ওপর ৫% মাসিক বেতন ও ২% ট্যুর ফান্ড',
    'manual_ch_subdealer_salary_tour_badge' => 'সাব-ডিলারের আয়',
    'manual_ch_subdealer_salary_tour_summary' => 'সাব-ডিলারের কেনার ওপর ৫% মাসিক বেতন, ২% বিদেশ ভ্রমণ (ট্যুর) ফান্ড এবং স্পন্সরের বিশেষ রেটের সুবিধা।',
    'manual_ch_subdealer_salary_tour_purpose' => 'সাব-ডিলার প্ল্যানটি দোকানদার ও স্থানীয় বিক্রেতাদের জন্য একটি বিশেষ আয়ের ব্যবস্থা। প্রতি মাসে মোট পণ্য কেনার ওপর ৫% হারে বেতন দেওয়া হয় এবং আরও ২% টাকা আপনা থেকে তাদের বিদেশ ভ্রমণ ফান্ডে জমা হয়।',
    'manual_ch_subdealer_salary_tour_why' => 'ছোট ও মাঝারি দোকানদারদের নিয়মিত মাসিক আয় দেয় এবং দীর্ঘ সময় ব্যবসার সাথে যুক্ত রাখে। এতে প্রতি মাসে নগদ বেতন ও বছরে বিদেশ ভ্রমণের সুযোগ মেলে।',
    'manual_ch_subdealer_salary_tour_s1' => 'সাব-ডিলার অ্যাকাউন্টে লগইন করে বাম মেনুর "বেতন ও ট্যুর" অংশ খুলুন।',
    'manual_ch_subdealer_salary_tour_s2' => 'চলতি মাসের যোগ্য কেনাকাটা এবং এখন পর্যন্ত জমা হওয়া ৫% বেতন দেখুন।',
    'manual_ch_subdealer_salary_tour_s3' => '"ট্যুর ফান্ড" কার্ডে আপনার জমানো ২% ভ্রমণ ফান্ডের মোট টাকা এবং পরের ট্যুরের গন্তব্য দেখুন।',
    'manual_ch_subdealer_salary_tour_s4' => 'বেতন পেতে চলতি মাসে কোম্পানির ঠিক করা ন্যূনতম কেনাকাটা (যেমন ৳১০,০০০ বা নিয়মে যা আছে) পূরণ করুন।',
    'manual_ch_subdealer_salary_tour_s5' => 'মাস শেষে কোম্পানির হিসাব বিভাগ হিসাব মিলিয়ে ৫% বেতনের টাকা সরাসরি আপনার ওয়ালেটের তোলার যোগ্য ব্যালেন্সে পাঠিয়ে দেবে।',
    'manual_ch_subdealer_salary_tour_s6' => 'জমা হওয়া বেতন সাধারণ কমিশনের মতোই সঙ্গে সঙ্গে ব্যাংক বা মোবাইল ব্যাংকিংয়ে (বিকাশ/নগদ) তুলতে পারবেন।',
    'manual_ch_subdealer_salary_tour_out1' => 'বেতনের এন্ট্রি হিসাব খাতায় যোগ হয় এবং ওয়ালেট ব্যালেন্স আপনা থেকে বাড়ে।',
    'manual_ch_subdealer_salary_tour_out2' => 'ট্যুর ফান্ডে ২% টাকা যোগ হয়, যা কোম্পানির অফিসিয়াল ভ্রমণে আপনার টিকিট ও ভিসার খরচে কাজে লাগে।',
    'manual_ch_subdealer_salary_tour_out3' => 'সাব-ডিলারের স্পন্সর ডিলার তার কেনাকাটার ওপর বিশেষ রেটের বোনাস পান।',
    'manual_ch_subdealer_salary_tour_rule1' => 'বেতন পেতে সেই মাসে ন্যূনতম কেনাকাটা পূরণ করতেই হবে।',
    'manual_ch_subdealer_salary_tour_rule2' => 'ট্যুর ফান্ডের টাকা শুধু কোম্পানির অফিসিয়াল ভ্রমণের জন্য; এটি নগদে তোলা যায় না।',
    'manual_ch_subdealer_salary_tour_rule3' => 'সাব-ডিলার পরে পূর্ণ ডিলার হলে তার ট্যুর ফান্ড আপনা থেকে নতুন অ্যাকাউন্টে চলে যাবে।',
    'manual_ch_subdealer_salary_tour_t1' => 'মাসের শেষ সপ্তাহের জন্য অপেক্ষা না করে প্রতি সপ্তাহে ছোট ছোট অর্ডারের মাধ্যমে লক্ষ্যমাত্রা পূরণ করে ফেলুন।',
    'manual_ch_subdealer_salary_tour_t2' => 'ট্যুর ফান্ডের অগ্রগতি দেখুন, যাতে বুঝতে পারেন কোম্পানির বার্ষিক বিদেশ ভ্রমণে কবে যোগ্য হবেন।',
    'manual_ch_subdealer_salary_tour_warn1' => 'রিটার্ন বা বাতিল হওয়া অর্ডারের জন্য বেতনের সেই অংশ সঙ্গে সঙ্গে কেটে নেওয়া হবে।',
    'manual_ch_subdealer_salary_tour_warn2' => 'ভুয়া অর্ডার দিয়ে বেতন দাবি করা শৃঙ্খলাভঙ্গ; তদন্ত করে অ্যাকাউন্ট বন্ধ করা হতে পারে।',
    'manual_ch_subdealer_salary_tour_q1' => 'আমি কি বেতনের টাকা বিকাশ বা ব্যাংকে তুলতে পারব?',
    'manual_ch_subdealer_salary_tour_a1' => 'হ্যাঁ! বেতন ওয়ালেটে জমা হওয়ার পর আপনি বিকাশ, নগদ, রকেট বা যেকোনো ব্যাংক অ্যাকাউন্টে তা তুলতে পারবেন।',
    'manual_ch_subdealer_salary_tour_q2' => 'ট্যুর ফান্ডের টাকা দিয়ে কোথায় যাওয়া হয়?',
    'manual_ch_subdealer_salary_tour_a2' => 'কোম্পানি প্রতি বছর ব্যাংকক, মালয়েশিয়া, দুবাই বা তুরস্ক ভ্রমণের আয়োজন করে। আপনার যোগ্যতার স্তর অনুযায়ী ট্যুর প্যাকেজ ঠিক হয়।',
    // Chapter 11: withdrawals
    'manual_ch_withdrawals_title' => '১১. পার্টনার ওয়ালেট, টাকা তোলার অনুরোধ ও পেমেন্ট',
    'manual_ch_withdrawals_badge' => 'ওয়ালেট ও পেমেন্ট',
    'manual_ch_withdrawals_summary' => 'তোলার যোগ্য ও অপেক্ষমাণ ব্যালেন্স, সর্বনিম্ন ৳৫০০ তোলার নিয়ম, ব্যাংক ও মোবাইল ব্যাংকিংয়ে (বিকাশ/নগদ/রকেট) পেমেন্ট এবং রসিদ যাচাই।',
    'manual_ch_withdrawals_purpose' => 'টাকা তোলার অংশ দিয়ে পার্টনাররা অর্জিত আয় নিরাপদে নিজের ব্যাংক বা মোবাইল ব্যাংকিং অ্যাকাউন্টে নেন। এখানে খাতা যাচাই, অনুমোদনের ধাপ এবং পেমেন্টের রসিদ রাখার ব্যবস্থা আছে।',
    'manual_ch_withdrawals_why' => 'পার্টনারদের পরিশ্রমের টাকা দ্রুত ও ঠিকভাবে পৌঁছে দেওয়াই এর মূল লক্ষ্য। কোনো লুকানো চার্জ নেই; প্রতিটি লেনদেনের TrxID, উৎসে কর (TDS)-এর তথ্য ও অফিসিয়াল রসিদ পিডিএফ আকারে ডাউনলোড করা যায়।',
    'manual_ch_withdrawals_s1' => 'মেনু থেকে "টাকা তোলা" অংশ খুলুন।',
    'manual_ch_withdrawals_s2' => 'আপনার তোলার যোগ্য ব্যালেন্স দেখুন; এটি অবশ্যই কমপক্ষে ৳৫০০ হতে হবে।',
    'manual_ch_withdrawals_s3' => 'টাকা তোলার অনুরোধের বাটনে চাপ দিয়ে ফর্মটি খুলুন।',
    'manual_ch_withdrawals_s4' => 'টাকার পরিমাণ লিখুন এবং কোথায় নেবেন বেছে নিন (ব্যাংক ট্রান্সফার, বিকাশ, নগদ বা রকেট)।',
    'manual_ch_withdrawals_s5' => 'নির্বাচিত মাধ্যমের প্রয়োজনীয় তথ্য (যেমন: ব্যাংকের নাম, ব্রাঞ্চ, অ্যাকাউন্ট নম্বর, রাউটিং নম্বর অথবা মোবাইল ব্যাংকিং নম্বর) দিন।',
    'manual_ch_withdrawals_s6' => 'অনুরোধ জমার বাটনে চাপ দিন; অনুরোধটি সঙ্গে সঙ্গে যাচাইয়ের অপেক্ষমাণ তালিকায় উঠবে।',
    'manual_ch_withdrawals_s7' => 'হিসাব বিভাগ যাচাই করে টাকা পাঠানোর পর TrxID ও পেমেন্ট স্লিপ আপলোড করবে।',
    'manual_ch_withdrawals_s8' => 'টাকা পাঠানো হলে অবস্থা "পরিশোধিত" দেখাবে; তখন রসিদ ডাউনলোড বাটনে চাপ দিয়ে রসিদ সেভ করে রাখুন।',
    'manual_ch_withdrawals_out1' => 'অনুরোধ জমার সঙ্গে সঙ্গে তোলার যোগ্য ব্যালেন্স থেকে সমপরিমাণ টাকা আটকে রাখা হয়, যাতে একই টাকা দুবার তোলা না যায়।',
    'manual_ch_withdrawals_out2' => 'হিসাব বিভাগে সঙ্গে সঙ্গে নোটিফিকেশন যায় এবং পেমেন্ট হলে ডিলারের ফোনে এসএমএস আসে।',
    'manual_ch_withdrawals_out3' => 'খাতায় খরচের (ডেবিট) এন্ট্রি বসে এবং ডিলারের ব্যাংক/মোবাইল অ্যাকাউন্টে টাকা জমা হয়।',
    'manual_ch_withdrawals_rule1' => 'সর্বনিম্ন ৳৫০০ তোলা যায়; এর কম টাকার জন্য অনুরোধ করা যাবে না।',
    'manual_ch_withdrawals_rule2' => 'সরকারি কর আইন অনুযায়ী প্রযোজ্য ক্ষেত্রে উৎসে কর (TDS) কাটা হয়, যা রসিদে লেখা থাকবে।',
    'manual_ch_withdrawals_rule3' => 'অ্যাকাউন্টে কোনো বকেয়া থাকলে আগে তা পরিশোধ করুন। বকেয়া শোধ না হওয়া পর্যন্ত নতুন টাকা তোলা বন্ধ থাকবে।',
    'manual_ch_withdrawals_t1' => 'সপ্তাহের কাজের দিনে (রবিবার থেকে বৃহস্পতিবার) ব্যাংক চলাকালীন সময়ে টাকা তোলার অনুরোধ পাঠালে দ্রুত পেমেন্ট সম্পন্ন হয়।',
    'manual_ch_withdrawals_t2' => 'সাবমিট করার আগে আপনার ১১ সংখ্যার বিকাশ/নগদ নম্বর দুবার মিলিয়ে নিন, যাতে টাকা ভুল নম্বরে না যায়।',
    'manual_ch_withdrawals_warn1' => 'ভুল ব্যাংক অ্যাকাউন্ট নম্বর বা অন্যের বিকাশ নম্বর দিলে টাকা ভুল জায়গায় যেতে পারে। এর দায় কোম্পানির নয়।',
    'manual_ch_withdrawals_warn2' => 'অস্বাভাবিক বা খুব বড় অনুরোধে পেমেন্টের আগে বাড়তি যাচাই হয়। কোম্পানি আপনার NID চাইতে পারে।',
    'manual_ch_withdrawals_q1' => 'টাকা পেতে কতক্ষণ সময় লাগে?',
    'manual_ch_withdrawals_a1' => 'বিকাশ ও নগদে সাধারণত ১২ থেকে ২৪ ঘণ্টার মধ্যে এবং ব্যাংক ট্রান্সফারে ১-২ কার্যদিবসের মধ্যে টাকা পৌঁছে যায়।',
    'manual_ch_withdrawals_q2' => 'আমার টাকা তোলার অনুরোধ কি বাতিল হতে পারে?',
    'manual_ch_withdrawals_a2' => 'হ্যাঁ। অ্যাকাউন্টের তথ্যে ভুল থাকলে বা বকেয়া বাকি থাকলে হিসাব বিভাগ কারণ লিখে অনুরোধটি বাতিল করতে পারে। তখন টাকা সঙ্গে সঙ্গে ওয়ালেটে ফেরত আসে।',
    // Chapter 12: reports
    'manual_ch_reports_title' => '১২. পূর্ণ রিপোর্ট, হিসাব খাতা ও ডাউনলোড',
    'manual_ch_reports_badge' => 'রিপোর্ট',
    'manual_ch_reports_summary' => 'তারিখ দিয়ে ফিল্টার করুন, কমিশনের বিস্তারিত, কেনাকাটা ও টাকা জমা-খরচের হিসাব দেখুন এবং PDF রিপোর্ট ডাউনলোড করুন।',
    'manual_ch_reports_purpose' => 'এই অংশে আপনার পুরো ব্যবসার হিসাব এক জায়গায় পাবেন: কত টাকার পণ্য কিনেছেন, কত কমিশন পেয়েছেন, কত উৎসে কর (TDS) কাটা হয়েছে, কত টাকা তুলেছেন এবং এখন কত পাওনা আছে।',
    'manual_ch_reports_why' => 'প্রতিটি লেনদেনের লিখিত হিসাব থাকলে ব্যবসা চালানো, কর রিটার্ন জমা দেওয়া এবং আসল লাভ কত তা বোঝা সহজ হয়।',
    'manual_ch_reports_s1' => 'সাইড মেনু থেকে "পূর্ণ রিপোর্ট" খুলুন।',
    'manual_ch_reports_s2' => 'ওপরের তারিখ ফিল্টার থেকে বেছে নিন: আজ, চলতি মাস, গত মাস, অথবা নিজের মতো শুরু ও শেষের তারিখ দিন।',
    'manual_ch_reports_s3' => 'ফিল্টার প্রয়োগ বাটনে ক্লিক করলে ওই সময়ের সব হিসাব দেখা যাবে।',
    'manual_ch_reports_s4' => 'সারসংক্ষেপ কার্ডে দেখুন: মোট কেনাকাটা, মোট কমিশন, মোট তোলা টাকা এবং শেষ ব্যালেন্স।',
    'manual_ch_reports_s5' => 'নিচে টিমের অংশে দেখুন আপনার টিমের কে কত টাকার ব্যবসা করেছেন।',
    'manual_ch_reports_s6' => 'পূর্ণ রিপোর্টের প্রিন্ট করার মতো কপি পেতে PDF ডাউনলোড বাটনে ক্লিক করুন।',
    'manual_ch_reports_out1' => 'রিপোর্ট আপনার হিসাব খাতার সব এন্ট্রি যোগ করে পুরো ব্যালেন্স দেখায়।',
    'manual_ch_reports_out2' => 'PDF-এ কোম্পানির তথ্য, তারিখ ও যাচাইয়ের QR কোড থাকে; সরাসরি প্রিন্ট করা যায়।',
    'manual_ch_reports_out3' => 'কোন পণ্য সবচেয়ে বেশি বিক্রি হয় এবং কখন বিক্রি বেশি হয়, তা দেখে ব্যবসার পরিকল্পনা করতে পারবেন।',
    'manual_ch_reports_rule1' => 'রিপোর্টের সব সংখ্যা জমা থাকা হিসাব থেকে আসে, যা বদলানো যায় না। কেউ হাতে এডিট করতে পারে না।',
    'manual_ch_reports_rule2' => 'নির্বাচিত তারিখে কোনো লেনদেন না থাকলে চার্ট খালি দেখাবে; এটি কোনো ভুল নয়।',
    'manual_ch_reports_rule3' => 'রিপোর্টের সমাপনী ব্যালেন্স সবসময় আপনার ওয়ালেটের বর্তমান ব্যালেন্সের সাথে হুবহু মিলে যাবে।',
    'manual_ch_reports_t1' => 'প্রতি মাসের ১ তারিখে পূর্ববর্তী মাসের সম্পূর্ণ রিপোর্টটি পিডিএফ হিসেবে ডাউনলোড করে আপনার ব্যক্তিগত ফাইলে সেভ করুন।',
    'manual_ch_reports_t2' => 'নিজের মতো তারিখ দিয়ে কোনো উৎসবের (যেমন ঈদ অফার) বিক্রি ও লাভ আলাদা করে দেখুন।',
    'manual_ch_reports_warn1' => 'ডাউনলোড করা রিপোর্টের PDF-এ কোনো কিছু বদলানো জালিয়াতি এবং আইনত দণ্ডনীয়।',
    'manual_ch_reports_warn2' => 'অনেক বড় রেঞ্জ (যেমন কয়েক বছর) নির্বাচন করলে ব্রাউজারে রিপোর্ট লোড হতে কয়েক সেকেন্ড অতিরিক্ত সময় লাগতে পারে।',
    'manual_ch_reports_q1' => 'রিপোর্টের ব্যালেন্স আর ওয়ালেটের ব্যালেন্সের মধ্যে কি পার্থক্য হতে পারে?',
    'manual_ch_reports_a1' => 'না। রিপোর্ট ও ওয়ালেট একই হিসাব খাতা থেকে আসে, তাই এক পয়সারও গরমিল হয় না।',
    'manual_ch_reports_q2' => 'আমি কি আমার ইনকাম ট্যাক্স রিটার্নে এই পিডিএফ ব্যবহার করতে পারব?',
    'manual_ch_reports_a2' => 'হ্যাঁ। এটি প্রতিটি লেনদেনসহ অফিসিয়াল ব্যবসায়িক স্টেটমেন্ট। আপনার আয় ও খরচের হিসাব হিসেবে এটি ব্যবহার করতে পারবেন।',
    // Chapter 13: treasury_capital_flow
    'manual_ch_treasury_capital_flow_title' => '১৩. কোম্পানির তহবিল, মূলধন ও ব্যাংক হিসাব',
    'manual_ch_treasury_capital_flow_badge' => 'কোম্পানি তহবিল ও মূলধন',
    'manual_ch_treasury_capital_flow_summary' => 'মোট আয়ের ৬০% কোম্পানির ভাগ, ব্যাংক ও মার্চেন্ট বিকাশ/নগদ অ্যাকাউন্ট, প্রতিদিনের ক্যাশ হিসাব মেলানো এবং হাতে থাকা নগদ টাকার তহবিল।',
    'manual_ch_treasury_capital_flow_purpose' => 'এই অংশটি মালিক ও হিসাব বিভাগের জন্য। এখানে কোম্পানির সব টাকার হিসাব দেখা যায়: ব্যাংক ও বিকাশ/নগদে কত টাকা এলো, কীভাবে তা ৬০% কোম্পানির ভাগ ও ৪০% পার্টনার কমিশনে ভাগ হলো, এবং প্রতিদিনের খরচের জন্য কত নগদ আছে।',
    'manual_ch_treasury_capital_flow_why' => 'কোম্পানির হাতে সবসময় কাঁচামাল কেনা ও প্রতিদিনের খরচের মতো যথেষ্ট টাকা আছে কিনা, তা নিশ্চিত করতে এই হিসাব দরকার। এতে সব ব্যাংক ও মার্চেন্ট অ্যাকাউন্টের হিসাব পরিষ্কার থাকে।',
    'manual_ch_treasury_capital_flow_s1' => 'মালিক বা অ্যাডমিন অ্যাকাউন্ট থেকে সাইড মেনুর হিসাব অংশে "কোম্পানি তহবিল" খুলুন।',
    'manual_ch_treasury_capital_flow_s2' => 'চার্টে দেখুন মোট আয় কীভাবে ৬০% কোম্পানি তহবিল ও ৪০% পার্টনার কমিশন তহবিলে ভাগ হয়েছে।',
    'manual_ch_treasury_capital_flow_s3' => 'পেমেন্ট অ্যাকাউন্ট ট্যাবে কোম্পানির ব্যাংক অ্যাকাউন্ট (যেমন City Bank, Dutch Bangla, Islami Bank) ও মার্চেন্ট বিকাশ/নগদের ব্যালেন্স দেখুন।',
    'manual_ch_treasury_capital_flow_s4' => 'প্রতিদিনের জমার তালিকা দেখে বুঝুন কোন অ্যাকাউন্টে কত টাকা জমা হয়েছে।',
    'manual_ch_treasury_capital_flow_s5' => 'চলতি খরচ ও সাপ্লায়ারের পেমেন্টের জন্য কোম্পানির তহবিল থেকে টাকা আলাদা করে রাখুন ও অনুমোদন দিন।',
    'manual_ch_treasury_capital_flow_s6' => 'কোম্পানির হিসাব খাতার সাথে ব্যাংক স্টেটমেন্ট মিলিয়ে "হিসাব মেলান" নিশ্চিত করুন।',
    'manual_ch_treasury_capital_flow_out1' => 'প্রতিটি অর্ডারের পেমেন্ট অনুমোদন হলে সঙ্গে সঙ্গে টাকা ৬০/৪০ ভাগে কোম্পানির হিসাবে যোগ হয়।',
    'manual_ch_treasury_capital_flow_out2' => 'সব পেমেন্ট অ্যাকাউন্টের হিসাব কোনো গরমিল ছাড়াই মিলে যায়।',
    'manual_ch_treasury_capital_flow_out3' => 'নগদ টাকা কমে যাওয়ার আশঙ্কা আগেই জানা যায়, তাই কাঁচামাল কেনার পরিকল্পনা করা সহজ হয়।',
    'manual_ch_treasury_capital_flow_rule1' => 'কোম্পানি তহবিলের পাতা শুধু মালিক ও অনুমোদিত হিসাব বিভাগের লোকজন খুলতে পারেন।',
    'manual_ch_treasury_capital_flow_rule2' => 'কোম্পানির তহবিল থেকে মূলধন তুলতে দুজনের অনুমোদন লাগে, যার মধ্যে মালিকের সম্মতি থাকতে হবে।',
    'manual_ch_treasury_capital_flow_rule3' => 'প্রতি কর্মদিবসের শেষে জমার অ্যাকাউন্টগুলোর হিসাব ব্যাংক ব্যালেন্সের সাথে মিলিয়ে নিতে হবে।',
    'manual_ch_treasury_capital_flow_t1' => 'মার্চেন্ট বিকাশ ও নগদের দৈনিক ক্যাশ-ইন লিমিটের দিকে নজর রাখুন, যাতে ডিলারদের পেমেন্ট আটকে না যায়।',
    'manual_ch_treasury_capital_flow_t2' => 'ব্যাংক ছুটির আগে পেমেন্ট অ্যাকাউন্টে যথেষ্ট নগদ টাকা রাখুন, যাতে জরুরি পেমেন্ট ও সরবরাহ বন্ধ না হয়।',
    'manual_ch_treasury_capital_flow_warn1' => 'অনুমতি ছাড়া কেউ কোম্পানি তহবিলের তথ্য দেখতে বা বদলাতে পারবেন না; এমন চেষ্টা হলে অ্যাডমিনের কাছে সতর্কবার্তা যায়।',
    'manual_ch_treasury_capital_flow_warn2' => 'ব্যাংকের হিসাব মেলাতে গিয়ে কোনো অমিল পেলে সঙ্গে সঙ্গে কাজ থামিয়ে খোঁজ নিন।',
    'manual_ch_treasury_capital_flow_q1' => 'কোম্পানির ৬০% তহবিল কী কাজে লাগে?',
    'manual_ch_treasury_capital_flow_a1' => 'এই টাকা দিয়ে পণ্য তৈরি, কাঁচামাল আমদানি, গুদাম চালানো, কর্মচারীদের বেতন এবং কোম্পানির ব্যবসা বাড়ানোর খরচ চলে।',
    'manual_ch_treasury_capital_flow_q2' => 'পার্টনারদের পেমেন্ট কি সরাসরি কোম্পানির তহবিল থেকে পাঠানো হয়?',
    'manual_ch_treasury_capital_flow_a2' => 'না। পার্টনারদের টাকা পাঠাতে আলাদা অ্যাকাউন্ট ব্যবহার হয়, যা কোম্পানির মূল তহবিল থেকে আলাদা থাকে।',
    // Chapter 14: owner_benefits_fund
    'manual_ch_owner_benefits_fund_title' => '১৪. বিশেষ বেনিফিট ফান্ড (শুধু মালিক)',
    'manual_ch_owner_benefits_fund_badge' => 'শুধু মালিক',
    'manual_ch_owner_benefits_fund_summary' => 'মালিকের গোপন হিসাব খাতা: কমিশন দেওয়ার পর থাকা লাভের অংশ, মালিকের লভ্যাংশ তহবিল এবং আলাদা যাচাই।',
    'manual_ch_owner_benefits_fund_purpose' => 'বিশেষ বেনিফিট ফান্ড হলো শুধু মালিকের জন্য তৈরি গোপন হিসাব খাতা। শেষ হওয়া অর্ডারের লাভ থেকে মালিকের প্রাপ্য অংশ এখানে জমা হয়। সাধারণ স্টাফ ও ডিলাররা এটি দেখতে পারেন না।',
    'manual_ch_owner_benefits_fund_why' => 'এই ফান্ড আলাদা রাখলে মালিকের বিনিয়োগ নিরাপদ থাকে এবং ভবিষ্যতে আবার বিনিয়োগ ও ব্যবসা বাড়ানোর জন্য টাকা জমে।',
    'manual_ch_owner_benefits_fund_s1' => 'শুধু সুপার অ্যাডমিন / মালিক অ্যাকাউন্টে লগইন করে সাইড মেনু থেকে "বিশেষ বেনিফিট ফান্ড" খুলুন।',
    'manual_ch_owner_benefits_fund_s2' => 'ফান্ডের মোট জমা ব্যালেন্স এবং চলতি অর্থবছরে কত বেড়েছে তা দেখুন।',
    'manual_ch_owner_benefits_fund_s3' => 'প্রতিটি অর্ডারের এন্ট্রি দেখুন: অর্ডার নম্বর, ক্রেতা, ইনভয়েসের মোট টাকা, দেওয়া কমিশন এবং মালিকের অংশ।',
    'manual_ch_owner_benefits_fund_s4' => 'ফান্ডের টাকা আবার বিনিয়োগ করা অথবা মালিকের লভ্যাংশ হিসেবে তোলার অনুমোদন দিন।',
    'manual_ch_owner_benefits_fund_s5' => 'হিসাবের ইতিহাস দেখে নিশ্চিত হোন যে সব ভাগ দেওয়ার পর কোনো উদ্বৃত্ত টাকা হারিয়ে যায়নি।',
    'manual_ch_owner_benefits_fund_s6' => 'বছর শেষের কর ও হিসাব যাচাইয়ের জন্য ফান্ডের গোপন স্টেটমেন্ট ডাউনলোড করুন।',
    'manual_ch_owner_benefits_fund_out1' => 'প্রতিটি অর্ডার শেষ হলে লাভের মালিকানা অংশ আপনা থেকেই ফান্ডের খাতায় জমা হয়।',
    'manual_ch_owner_benefits_fund_out2' => 'কোম্পানির নিট সম্পদ বাড়ে এবং প্রতিটি পরিবর্তনের রেকর্ড থাকে।',
    'manual_ch_owner_benefits_fund_out3' => 'এই ফান্ডের কোনো তথ্য ডিলার, সাব-ডিলার বা সাধারণ কর্মচারীর প্যানেলে দেখা যায় না।',
    'manual_ch_owner_benefits_fund_rule1' => 'এই অংশে শুধু মালিক ঢুকতে পারেন; কোনো কর্মচারী বা ম্যানেজার পারেন না।',
    'manual_ch_owner_benefits_fund_rule2' => 'ফান্ডের প্রতিটি এন্ট্রি লক করা থাকে; পুরনো কোনো এন্ট্রি বদলানো বা মুছে ফেলা যায় না।',
    'manual_ch_owner_benefits_fund_rule3' => 'পার্টনারদের সব কমিশন ও অন্যান্য খরচ দেওয়ার পরই মালিকের অংশ হিসাব হয়।',
    'manual_ch_owner_benefits_fund_t1' => 'প্রতিমাসের শেষে ওনার ফান্ডের গ্রোথ চেক করে ভবিষ্যৎ কাঁচামাল আমদানি ও ফ্যাক্টরি সম্প্রসারণের পরিকল্পনা তৈরি করুন।',
    'manual_ch_owner_benefits_fund_t2' => 'মালিকের অ্যাকাউন্টে শক্ত পাসওয়ার্ড দিন এবং দুই ধাপের লগইন (2FA) চালু রাখুন।',
    'manual_ch_owner_benefits_fund_warn1' => 'এই ফান্ডের তথ্য সম্পূর্ণ গোপন; অনুমতি ছাড়া কাউকে স্ক্রিনশট বা হিসাব দেখাবেন না।',
    'manual_ch_owner_benefits_fund_warn2' => 'মালিকের লগইন তথ্য অফিসের কোনো স্টাফকে দেবেন না।',
    'manual_ch_owner_benefits_fund_q1' => 'স্টাফ বা ম্যানেজাররা কি বিশেষ বেনিফিট ফান্ড দেখতে পারেন?',
    'manual_ch_owner_benefits_fund_a1' => 'না। কর্মচারীদের প্যানেলে এই অংশটি নেই এবং সার্ভার থেকেই সব স্টাফ অ্যাকাউন্টের জন্য বন্ধ করা আছে।',
    'manual_ch_owner_benefits_fund_q2' => 'মালিকের ফান্ডের টাকা কি পার্টনার কমিশনের সাথে জড়িত?',
    'manual_ch_owner_benefits_fund_a2' => 'না। পার্টনারদের ৪০% কমিশন সম্পূর্ণ আলাদাভাবে দেওয়া হয়। মালিকের ফান্ড আসে কোম্পানির ৬০% ভাগে যে টাকা উদ্বৃত্ত থাকে, তা থেকে।',
    // Chapter 15: staff_ops
    'manual_ch_staff_ops_title' => '১৫. স্টাফের কাজ, অনুমতি ও ড্যাশবোর্ড বদল',
    'manual_ch_staff_ops_badge' => 'স্টাফ পরিচালনা',
    'manual_ch_staff_ops_summary' => 'অ্যাকাউন্টস, ডেলিভারি, স্টক ও সাপোর্ট স্টাফদের কাজ অনুযায়ী অনুমতি দেওয়া, টাকা দেওয়ার অনুমোদন, অর্ডারের কাজ, এবং যে ডিলার স্টাফও, তার জন্য দুই ড্যাশবোর্ডে যাওয়ার সুবিধা।',
    'manual_ch_staff_ops_purpose' => 'এখানে কর্মচারীরা প্রতিদিনের কাজ করেন: অর্ডার প্যাক ও পাঠানো, পেমেন্ট দাবি যাচাই, টাকা তোলার অনুমোদন এবং সাপোর্ট অনুরোধের উত্তর। প্রত্যেকে শুধু নিজের কাজের অনুমতি পান, যাতে একজনের হাতে সব দায়িত্ব না থাকে।',
    'manual_ch_staff_ops_why' => 'ভুল ও জালিয়াতি ঠেকাতে প্রত্যেক কর্মচারীকে শুধু তার কাজের অনুমতি (যেমন শুধু স্টক বা শুধু হিসাব) দিতে হয়। তখন কোনো একজনের হাতে টাকা ও স্টক দুটোই থাকে না, আর সব কাজের রেকর্ড ঠিক থাকে।',
    'manual_ch_staff_ops_s1' => 'সুপার অ্যাডমিন হিসেবে লগইন করে সাইড মেনু থেকে "কর্মচারী ও স্টাফ" খুলুন।',
    'manual_ch_staff_ops_s2' => 'নতুন স্টাফ অ্যাকাউন্ট তৈরির বাটনে ক্লিক করে কর্মচারীর নাম, মোবাইল নম্বর, ইমেইল ও প্রথম পাসওয়ার্ড দিন।',
    'manual_ch_staff_ops_s3' => 'কাজ অনুযায়ী অনুমতির ঘরে টিক দিন: হিসাব (টাকা ও পেমেন্ট), অর্ডার (অর্ডার অনুমোদন), স্টক (স্টক আনা-নেওয়া), সাপোর্ট (অনুরোধের উত্তর) ইত্যাদি।',
    'manual_ch_staff_ops_s4' => 'কর্মচারী লগইন করলে শুধু তার অনুমতি থাকা মেনুগুলোই দেখবেন; বাকিগুলো দেখা যাবে না।',
    'manual_ch_staff_ops_s5' => 'কোনো ডিলার বা সাব-ডিলার যদি কোম্পানির কর্মচারীও হন, তবে সুপার অ্যাডমিন তার অ্যাকাউন্টে স্টাফ অনুমতি দিতে পারেন।',
    'manual_ch_staff_ops_s6' => 'এমন ব্যবহারকারী প্রোফাইল মেনু থেকে এক ক্লিকে "স্টাফ ড্যাশবোর্ডে যান" এবং আবার "আমার দোকানের ড্যাশবোর্ডে যান" বেছে নিতে পারবেন।',
    'manual_ch_staff_ops_out1' => 'প্রতিটি কর্মচারী অ্যাকাউন্টের নিজস্ব অনুমতি থাকে এবং প্রতিটি কাজ কে করেছেন তা রেকর্ড হয়।',
    'manual_ch_staff_ops_out2' => 'দুই ড্যাশবোর্ডের সুবিধায় একজন ব্যবহারকারী নিজের ডিলারশিপ ও অফিসের কাজ একই লগইনে নিরাপদে চালাতে পারেন।',
    'manual_ch_staff_ops_out3' => 'ডেলিভারি, হিসাব ও সাপোর্টের কাজ দ্রুত ও নির্ভুলভাবে হয়, এবং কার দায়িত্ব কী তা পরিষ্কার থাকে।',
    'manual_ch_staff_ops_rule1' => 'কোনো কর্মচারী নিজের অনুমতি নিজে বাড়াতে বা বদলাতে পারবেন না; এটি শুধু মালিক বা সুপার অ্যাডমিন পারেন।',
    'manual_ch_staff_ops_rule2' => 'কোনো পেমেন্ট রেকর্ড করার সময় আসল ব্যাংক স্লিপ বা পেমেন্টের প্রমাণ আপলোড করা বাধ্যতামূলক।',
    'manual_ch_staff_ops_rule3' => 'ড্যাশবোর্ড বদলালেও পার্টনারের নিজের কমিশন ও ওয়ালেট কোম্পানির টাকার সাথে মিশবে না; হিসাব সম্পূর্ণ আলাদা থাকবে।',
    'manual_ch_staff_ops_t1' => 'কয়েক মাস পর পর কর্মচারীদের অনুমতি যাচাই করুন এবং কেউ চাকরি ছাড়লে সঙ্গে সঙ্গে অ্যাকাউন্ট বন্ধ করুন।',
    'manual_ch_staff_ops_t2' => 'দুই ড্যাশবোর্ড ব্যবহারকারীদের বলুন, অর্ডার অনুমোদন বা পেমেন্ট রেকর্ডের আগে দেখে নিতে তারা কোন ড্যাশবোর্ডে আছেন।',
    'manual_ch_staff_ops_warn1' => 'একই কর্মচারীকে একসাথে স্টক ছাড়া ও টাকা দেওয়ার অনুমতি দেবেন না; কাজ ভাগ করে রাখুন।',
    'manual_ch_staff_ops_warn2' => 'কর্মচারীরা কখনো নিজের লগইন পাসওয়ার্ড অন্য কাউকে দেবেন না; দিলে সঙ্গে সঙ্গে অ্যাকাউন্ট বন্ধ হতে পারে।',
    'manual_ch_staff_ops_q1' => 'আমি কীভাবে দোকানের ড্যাশবোর্ড থেকে স্টাফ ড্যাশবোর্ডে যাব?',
    'manual_ch_staff_ops_a1' => 'আপনার অ্যাকাউন্টে স্টাফ অনুমতি থাকলে ওপরে ডানদিকের প্রোফাইল মেনুতে ক্লিক করে "স্টাফ ড্যাশবোর্ডে যান" বেছে নিন।',
    'manual_ch_staff_ops_q2' => 'স্টাফের কোনো ভুল হলে কি ঠিক করা যায়?',
    'manual_ch_staff_ops_a2' => 'হ্যাঁ। সুপার অ্যাডমিন কাজের রেকর্ড দেখে যেকোনো ভুল ঠিক বা ফেরত করতে পারেন।',
    // Chapter 16: website_customization
    'manual_ch_website_customization_title' => '১৬. ওয়েবসাইটের কন্টেন্ট, ব্যানার, নোটিশ ও গ্রাহকের বার্তা',
    'manual_ch_website_customization_badge' => 'ওয়েবসাইট কন্টেন্ট',
    'manual_ch_website_customization_summary' => 'ওয়েবসাইটের হোমপেজ ব্যানার ও স্লাইডার বদলানো, নোটিশ ও মূল্যের সার্কুলার প্রকাশ, গ্রাহকের বার্তার উত্তর দেওয়া এবং গুগল ম্যাপের লোকেশন ঠিক করা।',
    'manual_ch_website_customization_purpose' => 'এখান থেকে মদিনার পাবলিক ওয়েবসাইট চালানো হয়। কোনো কোডিং ছাড়াই ব্যানার, বিশেষ অফার, অফিসিয়াল সার্কুলার, পণ্যের প্রদর্শন এবং গ্রাহকদের পাঠানো বার্তা দেখা ও বদলানো যায়।',
    'manual_ch_website_customization_why' => 'নতুন অফার, নতুন পণ্য ও জরুরি নোটিশ দ্রুত গ্রাহক ও ডিলারদের কাছে পৌঁছানো জরুরি। এতে ব্র্যান্ডের সুনাম বাড়ে এবং বিক্রি বাড়ে।',
    'manual_ch_website_customization_s1' => 'সাইড মেনু থেকে "ওয়েবসাইট ব্যবস্থাপনা" খুলুন।',
    'manual_ch_website_customization_s2' => 'হোমপেজ ব্যানার ট্যাবে গিয়ে নতুন অফারের পরিষ্কার ছবি আপলোড করুন এবং শিরোনাম ও ছোট লেখা দিন।',
    'manual_ch_website_customization_s3' => 'নোটিশ ট্যাবে গিয়ে নতুন সার্কুলার লিখুন: শিরোনাম, ক্যাটাগরি ও পুরো লেখা দিয়ে প্রকাশ বাটনে ক্লিক করুন।',
    'manual_ch_website_customization_s4' => 'প্রকাশিত নোটিশ সঙ্গে সঙ্গে সব ডিলার ও সাব-ডিলারের নোটিশ পাতায় এবং পাবলিক ওয়েবসাইটে দেখা যাবে।',
    'manual_ch_website_customization_s5' => '"জিজ্ঞাসা" অংশে গিয়ে ভিজিটরদের পাঠানো পণ্যের প্রশ্ন বা ডিলারশিপের আবেদন দেখুন।',
    'manual_ch_website_customization_s6' => 'প্রতিটি জিজ্ঞাসার উত্তর দিন, অথবা সংশ্লিষ্ট এরিয়া ডিলারের কাছে কাস্টমার হিসেবে পাঠিয়ে দিন।',
    'manual_ch_website_customization_out1' => 'নতুন ব্যানার ও অফার সঙ্গে সঙ্গে ওয়েবসাইটে চালু হয়।',
    'manual_ch_website_customization_out2' => 'জরুরি সার্কুলার প্রকাশ হলেই ডিলার প্যানেলে নোটিফিকেশন যায়।',
    'manual_ch_website_customization_out3' => 'জিজ্ঞাসার ঠিকমতো ফলোআপ করলে নতুন কাস্টমার ও ডিলার পাওয়া যায়, বিক্রি বাড়ে।',
    'manual_ch_website_customization_rule1' => 'ব্যানার আপলোডের সময় সুপারিশ করা সাইজ (যেমন 1920x600 পিক্সেল) ও পরিষ্কার ছবি ব্যবহার করুন, যাতে মোবাইল ও কম্পিউটারে ভালো দেখায়।',
    'manual_ch_website_customization_rule2' => 'অফিসিয়াল সার্কুলার প্রকাশের আগে বানান ও তথ্য ঠিক আছে কিনা দেখে নিন; কারণ এটি অফিসিয়াল ঘোষণা হিসেবে ধরা হয়।',
    'manual_ch_website_customization_rule3' => 'গ্রাহকদের বার্তার উত্তর ২৪ ঘণ্টার মধ্যে দিতে হবে।',
    'manual_ch_website_customization_t1' => 'উৎসবের মৌসুমের আগে (যেমন ঈদ বা বৈশাখ) আকর্ষণীয় অফার ব্যানার দিয়ে ওয়েবসাইট সাজান।',
    'manual_ch_website_customization_t2' => 'সার্কুলার লেখার সময় গুরুত্বপূর্ণ কথা ও তারিখ ছোট ছোট পয়েন্টে লিখুন, যাতে ডিলাররা সহজে বুঝতে পারেন।',
    'manual_ch_website_customization_warn1' => 'অনুমতি ছাড়া অন্যের ছবি বা লোগো ওয়েবসাইটে ব্যবহার করবেন না।',
    'manual_ch_website_customization_warn2' => 'ভুল দামের নোটিশ প্রকাশ করলে বিভ্রান্তি ও টাকার ঝামেলা হতে পারে; তাই প্রকাশের আগে দাম মিলিয়ে নিন।',
    'manual_ch_website_customization_q1' => 'প্রকাশিত কোনো সার্কুলার কি মুছে ফেলা বা সংশোধন করা যায়?',
    'manual_ch_website_customization_a1' => 'হ্যাঁ। নোটিশ পাতা থেকে যেকোনো নোটিশ এডিট করা, প্রকাশ বন্ধ করা বা মুছে ফেলা যায়।',
    'manual_ch_website_customization_q2' => 'ওয়েবসাইটের গুগল ম্যাপের অবস্থান কীভাবে পরিবর্তন করব?',
    'manual_ch_website_customization_a2' => 'ওয়েবসাইট ব্যবস্থাপনা পাতার ম্যাপ ও যোগাযোগ অংশে আপনার অফিসের গুগল ম্যাপের কোড বসিয়ে সেভ করুন।',
    // Chapter 17: support
    'manual_ch_support_title' => '১৭. সাহায্য, সাপোর্ট অনুরোধ ও সমস্যার সমাধান',
    'manual_ch_support_badge' => 'সাপোর্ট',
    'manual_ch_support_summary' => 'পেমেন্ট, দেরিতে আসা অর্ডার বা কমিশনের সমস্যা নিয়ে ছবি বা ফাইলসহ সাপোর্ট অনুরোধ পাঠান এবং উত্তর দেখুন।',
    'manual_ch_support_purpose' => 'অর্ডার, পেমেন্ট, ডেলিভারি বা কমিশনের যেকোনো সমস্যা জানানোর জায়গা এটি। ফোনকলের মতো নয়, এখানে প্রতিটি অনুরোধ লিখিত থাকে এবং সমাধান না হওয়া পর্যন্ত খোঁজ রাখা হয়।',
    'manual_ch_support_why' => 'কোনো সমস্যা দ্রুত সমাধান না হলে টাকার ক্ষতি হতে পারে। লিখিত অনুরোধে শুরু থেকে সমাধান পর্যন্ত প্রতিটি ধাপ দেখা যায় এবং কোনো অনুরোধ হারিয়ে যায় না।',
    'manual_ch_support_s1' => 'সাইড মেনু থেকে "ব্যবহার নির্দেশিকা ও সাপোর্ট" খুলুন।',
    'manual_ch_support_s2' => 'অনুরোধ পাঠানোর আগে এই নির্দেশিকার সার্চ বারে সমস্যার কথা লিখে খুঁজুন; উত্তর হয়তো এখানেই আছে।',
    'manual_ch_support_s3' => 'নির্দেশিকায় সমাধান না পেলে নিচের "সাহায্য চান" ফর্মে যান।',
    'manual_ch_support_s4' => 'বিষয় থেকে সমস্যার ধরন বেছে নিন: টাকা তোলা, কমিশন, অর্ডার বা ইনভয়েস, কারিগরি সমস্যা বা অন্যান্য।',
    'manual_ch_support_s5' => 'ছোট ও পরিষ্কার একটি শিরোনাম লিখুন এবং বিস্তারিত অংশে অর্ডার নম্বর বা TrxID দিন।',
    'manual_ch_support_s6' => 'প্রমাণ হিসেবে ব্যাংক স্লিপ, কুরিয়ারের রসিদ বা স্ক্রিনশট (.jpg, .png, .pdf) যুক্ত করুন।',
    'manual_ch_support_s7' => '"অনুরোধ পাঠান" বাটনে ক্লিক করুন; আপনি একটি অনুরোধ নম্বর পাবেন এবং সংশ্লিষ্ট টিম কাজ শুরু করবে।',
    'manual_ch_support_s8' => 'নিচে আপনার আগের সব অনুরোধের অবস্থা (অপেক্ষমাণ, কাজ চলছে, সমাধান হয়েছে) এবং সাপোর্ট টিমের উত্তর দেখুন।',
    'manual_ch_support_out1' => 'নতুন অনুরোধ সেভ হয় এবং বিষয় অনুযায়ী হিসাব বা ডেলিভারি টিমের ড্যাশবোর্ডে চলে যায়।',
    'manual_ch_support_out2' => 'সাপোর্ট টিম উত্তর দিলে আপনার প্যানেলে এবং ইমেইল/এসএমএসে বার্তা পৌঁছায়।',
    'manual_ch_support_out3' => 'সমস্যার সমাধান হলে অনুরোধটি "সমাধান হয়েছে" হিসেবে বন্ধ হয়, পুরো ইতিহাস রাখা থাকে এবং আপনি মতামত দিতে পারেন।',
    'manual_ch_support_rule1' => 'একই সমস্যার জন্য বারবার নতুন অনুরোধ খুলবেন না; আগের খোলা অনুরোধেই বার্তা দিন।',
    'manual_ch_support_rule2' => 'অনুরোধে অশালীন ভাষা বা অপ্রাসঙ্গিক কথা লেখা নিষেধ।',
    'manual_ch_support_rule3' => 'জরুরি পেমেন্ট বা ডেলিভারির সমস্যা অফিস সময়ের মধ্যে আগে সমাধান করা হয়।',
    'manual_ch_support_t1' => 'যত বেশি সম্ভব তথ্য দিন (যেমন TrxID, ইনভয়েস নম্বর, তারিখ ও সময়); এতে সমাধান দ্রুত হয়।',
    'manual_ch_support_t2' => 'ভুলের বার্তা বা ব্যাংকের এসএমএসের পরিষ্কার, পুরো স্ক্রিনশট দিন, যাতে টিম দ্রুত সমস্যা ধরতে পারে।',
    'manual_ch_support_warn1' => 'সাপোর্ট অনুরোধে ভুয়া ব্যাংক স্লিপ বা মিথ্যা তথ্য দেওয়া জালিয়াতি; এতে অ্যাকাউন্ট স্থগিত বা ডিলারশিপ বাতিল হতে পারে।',
    'manual_ch_support_warn2' => 'অনুরোধের সমাধান হলে সেটি বন্ধ করুন, যাতে তালিকা পরিষ্কার থাকে।',
    'manual_ch_support_q1' => 'সাপোর্ট অনুরোধ পাঠালে কতক্ষণের মধ্যে উত্তর পাব?',
    'manual_ch_support_a1' => 'আমাদের সাপোর্ট টিম সাধারণত ১ থেকে ৪ কর্মঘণ্টার মধ্যে প্রথম উত্তর দেয় এবং ২৪ ঘণ্টার মধ্যে সমস্যার সমাধান করার চেষ্টা করে।',
    'manual_ch_support_q2' => 'ছুটির দিনে কি সাপোর্ট চালু থাকে?',
    'manual_ch_support_a2' => 'হ্যাঁ, যেকোনো সময় অনুরোধ পাঠাতে পারেন। ছুটির দিনেও ডিউটিতে থাকা স্টাফ জরুরি পেমেন্ট ও ডেলিভারির অনুরোধ দেখেন।',
    // Chapter 18: inventory_branches
    'manual_ch_inventory_branches_title' => '১৮. শাখার স্টক, কেন্দ্রীয় গুদাম ও স্টক পাঠানো',
    'manual_ch_inventory_branches_badge' => 'গুদাম ও শাখার স্টক',
    'manual_ch_inventory_branches_summary' => 'কেন্দ্রীয় গুদাম ও আঞ্চলিক শাখাগুলোর লাইভ স্টক, শাখাভিত্তিক কর্মচারীর দায়িত্ব, স্টক পাঠানোর অনুমোদন এবং স্টক কম থাকার সতর্কতা।',
    'manual_ch_inventory_branches_purpose' => 'এই অংশে মদিনা ন্যাচারাল কেয়ারের কেন্দ্রীয় ফ্যাক্টরি গুদাম ও সারাদেশের শাখাগুলোর স্টক দেখা ও নিয়ন্ত্রণ করা হয়। প্রতিটি পণ্যের ব্যাচ নম্বর, মেয়াদ, হাতে থাকা পরিমাণ এবং শাখাভিত্তিক বিক্রি এখানে মেলানো হয়।',
    'manual_ch_inventory_branches_why' => 'স্টকের ঠিক হিসাব না থাকলে ডিলারদের সময়মতো পণ্য দেওয়া যায় না। কোনো শাখায় পণ্য কমে গেলে সিস্টেম জানিয়ে দেয়, যাতে কেন্দ্রীয় গুদাম থেকে দ্রুত স্টক পাঠানো যায়।',
    'manual_ch_inventory_branches_s1' => 'ব্যবস্থাপনা ড্যাশবোর্ডের পণ্য অংশ থেকে "স্টক" বা "শাখা" খুলুন।',
    'manual_ch_inventory_branches_s2' => 'শাখা বাছাইয়ের তালিকা থেকে একটি শাখা (যেমন ঢাকা কেন্দ্রীয় গুদাম, চট্টগ্রাম শাখা, রাজশাহী শাখা) বেছে নিন।',
    'manual_ch_inventory_branches_s3' => 'পণ্যের তালিকায় হাতে থাকা স্টক, অর্ডারের জন্য বুক করা স্টক এবং বিক্রির জন্য খালি থাকা পরিমাণ দেখুন।',
    'manual_ch_inventory_branches_s4' => 'এক শাখা থেকে অন্য শাখায় পণ্য পাঠাতে স্টক ট্রান্সফার বাটনে ক্লিক করুন।',
    'manual_ch_inventory_branches_s5' => 'কোন শাখা পাঠাবে, কোন শাখা পাবে, কোন পণ্য ও কত পরিমাণ—এসব দিয়ে চালান তৈরি করুন।',
    'manual_ch_inventory_branches_s6' => 'প্রাপক শাখা পণ্য হাতে পেয়ে গুনে মিলিয়ে গ্রহণ নিশ্চিত করার বাটনে ক্লিক করলে হিসাবে স্টক বদল সম্পন্ন হবে।',
    'manual_ch_inventory_branches_s7' => 'কোনো পণ্যের স্টক নির্দিষ্ট সীমার নিচে নামলেই লাল রঙের "স্টক কম" ব্যাজ দেখা যাবে।',
    'manual_ch_inventory_branches_out1' => 'পাঠানো শাখার স্টক থেকে পণ্য কমে যায় ও "পথে আছে" হিসেবে দেখায়; প্রাপক শাখা নিশ্চিত করলে সেখানে স্টক যোগ হয়।',
    'manual_ch_inventory_branches_out2' => 'ডিলাররা পণ্যের তালিকায় সবসময় সঠিক স্টক দেখতে পান, তাই ডেলিভারির সময় কোনো চমক থাকে না।',
    'manual_ch_inventory_branches_out3' => 'নষ্ট, মেয়াদোত্তীর্ণ বা ফেরত আসা স্টকের আলাদা ও পরিষ্কার রেকর্ড থাকে।',
    'manual_ch_inventory_branches_rule1' => 'হাতে গুনে না মিলিয়ে সিস্টেমে স্টক ঠিক করা বা ট্রান্সফার অনুমোদন করা যাবে না।',
    'manual_ch_inventory_branches_rule2' => 'কোনো শাখা যত স্টক আছে তার বেশি বিক্রি বা পাঠাতে পারবে না; সিস্টেম তা বন্ধ করে দেয়।',
    'manual_ch_inventory_branches_rule3' => 'প্রতিটি স্টক পাঠানোর সাথে পাঠানো ও গ্রহণকারী গুদাম কর্মীর নাম রেকর্ড থাকে।',
    'manual_ch_inventory_branches_t1' => 'প্রতি সপ্তাহে গুদামের তাকে থাকা পণ্য গুনে স্ক্রিনের স্টকের সাথে মিলিয়ে নিন।',
    'manual_ch_inventory_branches_t2' => 'সবচেয়ে বেশি বিক্রি হওয়া পণ্যের অন্তত ১৫ দিনের বাড়তি স্টক রাখুন, যাতে বড় অর্ডারে দেরি না হয়।',
    'manual_ch_inventory_branches_warn1' => 'প্রাপক শাখা নিশ্চিত না করা পর্যন্ত স্টক ট্রান্সফারকে শেষ ধরা যাবে না; পথে কোনো ক্ষতি হলে তা লিখে রাখুন।',
    'manual_ch_inventory_branches_warn2' => 'স্টকে গরমিল পেলে সঙ্গে সঙ্গে কাজ থামিয়ে খোঁজ নিন।',
    'manual_ch_inventory_branches_q1' => 'ডিলাররা কি সরাসরি শাখা থেকে পণ্য নিতে পারেন?',
    'manual_ch_inventory_branches_a1' => 'হ্যাঁ। অর্ডার দেওয়ার সময় শাখা থেকে নেওয়ার অপশন বেছে নিলে ইনভয়েস দেখিয়ে সংশ্লিষ্ট শাখা থেকে পণ্য নিতে পারবেন।',
    'manual_ch_inventory_branches_q2' => 'স্টক ট্রান্সফার দেখাতে কত সময় লাগে?',
    'manual_ch_inventory_branches_a2' => 'চালান তৈরি হলেই "পথে আছে" দেখায়, আর প্রাপক শাখা গ্রহণ নিশ্চিত করলেই সেখানে স্টক যোগ হয়।',
    // Chapter 19: payment_claims_gateways
    'manual_ch_payment_claims_gateways_title' => '১৯. পেমেন্টের মাধ্যম, TrxID ও ব্যাংক রসিদ যাচাই',
    'manual_ch_payment_claims_gateways_badge' => 'পেমেন্ট যাচাই',
    'manual_ch_payment_claims_gateways_summary' => 'বিকাশ, নগদ, রকেট বা ব্যাংকে টাকা পাঠানোর পর TrxID জমা, জমার রসিদ আপলোড, এবং হিসাব বিভাগ কীভাবে যাচাই ও হিসাব মেলায় তা জানুন।',
    'manual_ch_payment_claims_gateways_purpose' => 'এখানে আপনার অর্ডারের পেমেন্টের প্রমাণ জমা দেন: বিকাশ, নগদ, রকেটের TrxID, ব্যাংকের জমার স্লিপ বা EFTN/NPSB ট্রান্সফারের রসিদ। এরপর কোম্পানি তা নিজে বা আপনা থেকে যাচাই করে।',
    'manual_ch_payment_claims_gateways_why' => 'ভুয়া পেমেন্ট বা ভুল অ্যাকাউন্টে টাকা পাঠানো ঠেকাতে এই যাচাই দরকার। এতে প্রতিটি অর্ডারের টাকা কোম্পানির সঠিক অ্যাকাউন্টে এসেছে কিনা তার পরিষ্কার প্রমাণ থাকে।',
    'manual_ch_payment_claims_gateways_s1' => 'পেমেন্ট বাকি থাকা যেকোনো অর্ডার খুলে পেমেন্ট দাবি জমার বাটনে ক্লিক করুন।',
    'manual_ch_payment_claims_gateways_s2' => 'কোম্পানির পেমেন্ট অ্যাকাউন্টের তালিকা থেকে কোন অ্যাকাউন্টে টাকা পাঠিয়েছেন তা বেছে নিন (যেমন বিকাশ মার্চেন্ট, ডাচ-বাংলা ব্যাংক, সিটি ব্যাংক)।',
    'manual_ch_payment_claims_gateways_s3' => 'আপনার পাঠানো সঠিক টাকার পরিমাণ লিখুন।',
    'manual_ch_payment_claims_gateways_s4' => 'মোবাইল ব্যাংকিংয়ে পাওয়া ৮-১০ অক্ষরের TrxID, অথবা ব্যাংকের জমার স্লিপ / EFTN রেফারেন্স নম্বর দিন।',
    'manual_ch_payment_claims_gateways_s5' => 'ব্যাংকের জমার রসিদের ছবি বা PDF, অথবা মোবাইল পেমেন্ট সফল হওয়ার পরিষ্কার স্ক্রিনশট আপলোড করুন।',
    'manual_ch_payment_claims_gateways_s6' => 'জমা দিন বাটনে ক্লিক করুন; সঙ্গে সঙ্গে অবস্থা "যাচাইয়ের অপেক্ষায়" হবে।',
    'manual_ch_payment_claims_gateways_s7' => 'হিসাব বিভাগ ব্যাংক স্টেটমেন্ট দেখে পেমেন্ট মিলিয়ে নিলে আপনার অর্ডারের বকেয়া শূন্য হবে এবং অর্ডার পাঠানোর অনুমোদন হবে।',
    'manual_ch_payment_claims_gateways_out1' => 'পেমেন্ট দাবিটি অর্ডারের সাথে হিসাবে যোগ হয় এবং TrxID লক হয়ে যায়, যাতে একই TrxID দুবার ব্যবহার করা না যায়।',
    'manual_ch_payment_claims_gateways_out2' => 'হিসাব বিভাগে পেমেন্ট যাচাইয়ের সতর্কবার্তা পৌঁছায়।',
    'manual_ch_payment_claims_gateways_out3' => 'অনুমোদন হলেই অর্ডারের অবস্থা "পরিশোধিত" হয় এবং ইনভয়েসের ব্যালেন্স আপডেট হয়।',
    'manual_ch_payment_claims_gateways_rule1' => 'শুধু কোম্পানির অফিসিয়াল ব্যাংক অ্যাকাউন্ট ও মার্চেন্ট নম্বরে টাকা পাঠাবেন; কোনো কর্মচারীর ব্যক্তিগত নম্বরে টাকা পাঠানো সম্পূর্ণ নিষেধ।',
    'manual_ch_payment_claims_gateways_rule2' => 'একটি TrxID শুধু একবারই ব্যবহার করা যায়; আগে ব্যবহার হওয়া TrxID সিস্টেম নেয় না।',
    'manual_ch_payment_claims_gateways_rule3' => 'টাকা পাঠানোর পর ২৪ ঘণ্টার মধ্যে সিস্টেমে পেমেন্ট দাবি জমা দিতে হবে।',
    'manual_ch_payment_claims_gateways_t1' => 'ব্যাংকে টাকা জমার পর সিল ও সইসহ জমার স্লিপটি অর্ডার হাতে না পাওয়া পর্যন্ত যত্ন করে রাখুন।',
    'manual_ch_payment_claims_gateways_t2' => 'এসএমএস থেকে TrxID কপি করে সরাসরি পেস্ট করুন, যাতে কোনো অক্ষর ভুল না হয়।',
    'manual_ch_payment_claims_gateways_warn1' => 'ভুয়া, এডিট করা বা অন্যের TrxID ব্যবহার করা আইনত দণ্ডনীয় অপরাধ; এমন হলে অ্যাকাউন্ট সঙ্গে সঙ্গে বন্ধ করা হবে।',
    'manual_ch_payment_claims_gateways_warn2' => 'আপনার প্যানেলের পেমেন্ট অ্যাকাউন্ট পাতায় দেওয়া অ্যাকাউন্ট ছাড়া অন্য কোথাও টাকা পাঠাবেন না।',
    'manual_ch_payment_claims_gateways_q1' => 'আমি ভুল TrxID দিয়ে ফেলেছি, এখন কী করণীয়?',
    'manual_ch_payment_claims_gateways_a1' => 'সঙ্গে সঙ্গে সাহায্য অংশ থেকে সাপোর্ট অনুরোধ পাঠান এবং সঠিক TrxID ও জমার স্লিপের ছবি দিন। হিসাব বিভাগ নিজে ঠিক করে দেবে।',
    'manual_ch_payment_claims_gateways_q2' => 'পেমেন্ট যাচাই হতে কত সময় লাগে?',
    'manual_ch_payment_claims_gateways_a2' => 'অফিস সময়ে সাধারণত ৩০ মিনিট থেকে ২ ঘণ্টার মধ্যে ব্যাংক স্টেটমেন্ট দেখে পেমেন্ট অনুমোদন করা হয়।',
    // Chapter 20: commission_simulator
    'manual_ch_commission_simulator_title' => '২০. কমিশন পরীক্ষা ও ক্যালকুলেটর',
    'manual_ch_commission_simulator_badge' => 'কমিশন পরীক্ষা',
    'manual_ch_commission_simulator_summary' => 'লাইভ হিসাবে কোনো প্রভাব না ফেলে নতুন কমিশন নিয়ম ও রেট পরীক্ষা করুন, ডিলারদের কত টাকা দিতে হতে পারে তা দেখুন এবং ঝুঁকি বুঝে নিন।',
    'manual_ch_commission_simulator_purpose' => 'এটি পরীক্ষার পাতা। নতুন কমিশন রেট বা র‍্যাঙ্কের নিয়ম চালুর আগে মালিক পুরনো ও সম্ভাব্য বিক্রির ওপর চালিয়ে ফলাফল দেখতে পারেন, লাইভ হিসাব না বদলে।',
    'manual_ch_commission_simulator_why' => 'হুট করে কমিশন রেট বদলালে কোম্পানির লাভে ঝুঁকি তৈরি হতে পারে। এই পরীক্ষায় নিশ্চিত হওয়া যায় যে নতুন নিয়মেও কোম্পানির ৬০% ভাগ নিরাপদ থাকবে এবং ডিলারদের আয় ঠিক থাকবে।',
    'manual_ch_commission_simulator_s1' => 'সুপার অ্যাডমিন বা হিসাব বিভাগের প্রধান হিসেবে সাইড মেনুর ডিলার কমিশন অংশ থেকে "ক্যালকুলেটর" খুলুন।',
    'manual_ch_commission_simulator_s2' => 'যে পরিবর্তন পরীক্ষা করতে চান তা দিন: যেমন সরাসরি রেফার কমিশন %, স্তর বোনাসের হার বা র‍্যাঙ্ক বোনাস ফান্ডের শতাংশ।',
    'manual_ch_commission_simulator_s3' => 'পরীক্ষার জন্য বিক্রির সময়কাল বেছে নিন (যেমন "গত ৩ মাসের আসল বিক্রি" অথবা "সম্ভাব্য বিক্রি")।',
    'manual_ch_commission_simulator_s4' => 'চালানোর বাটনে ক্লিক করুন; লাইভ হিসাবে হাত না দিয়ে আলাদাভাবে পুরো হিসাব হবে।',
    'manual_ch_commission_simulator_s5' => 'ফলাফলের চার্টে দেখুন কোম্পানির সম্ভাব্য লাভ, ডিলারদের গড় আয় এবং মোট কত টাকা দিতে হবে।',
    'manual_ch_commission_simulator_s6' => 'ফলাফল ভালো ও লাভজনক হলে নতুন নিয়ম খসড়া হিসেবে সেভ করে বোর্ডের অনুমোদনের জন্য পাঠান।',
    'manual_ch_commission_simulator_out1' => 'নিয়ম বদলালে টাকার ওপর কী প্রভাব পড়বে, তার পরিষ্কার চার্ট ও পূর্বাভাস পাওয়া যায়।',
    'manual_ch_commission_simulator_out2' => 'পরীক্ষার কারণে লাইভ হিসাবে কোনো ভুল এন্ট্রি বা গোলমালের ঝুঁকি থাকে না।',
